/* lore/ru.lore.js — descriptions for the "Описание созвездий" tab (core/lore.js). v618 (owner): written in English first,
   from English-language sources (official books as summarised by the English wikis), in our own words; the other six
   languages are translated from the English. Loaded only when the tab is opened. */
KC.addLore("ru", {
  "dnd.c.artificer": "Изобретатель — мастер, для которого магия является ремеслом: он направляет заклинания через инструменты и устройства, а не через молитвы или старинные фолианты. Такие мастера наделяют обычные предметы магическими свойствами и на ходу чинят, улучшают и мастерят приспособления. Класс родом из мира Эберрон и также представлен в «Котле Таши со всякой всячиной».",
  "dnd.c.barbarian": "Варвар — свирепый воин, движимый первобытной яростью. В бою он впадает в Ярость: его удары становятся сильнее, а физический урон ему почти нипочём, и сражается он лучше всего в лёгком доспехе или вовсе без него, полагаясь на выносливость и чутьё. Многие варвары приходят с диких окраин цивилизации, но этот дар может питать любой глубокий источник гнева.",
  "dnd.c.bard": "Бард творит магию музыкой, словом и выступлением — в мире, который, по преданию, был создан словом. Барды поддерживают союзников Вдохновением барда, понемногу знают почти обо всём и владеют широким набором заклинаний для очарования, исцеления и обмана. Они объединяются в свободные коллегии, где делятся историями и приёмами.",
  "dnd.c.cleric": "Жрец — защитник веры, владеющий божественной магией, дарованной богом или высшей силой. Жрецы исцеляют и оберегают спутников, изгоняют нежить и призывают мощь своего божества через Божественный канал. Каждый служит определённому домену, который определяет его заклинания и дары.",
  "dnd.c.druid": "Друид — хранитель природного мира, черпающий силу из самой природы или от природных божеств. С помощью Дикого облика друиды принимают облик животных, а их заклинания призывают бури, залечивают раны и подчиняют растения и зверей. Они собираются в круги, разделяющие особый взгляд на силы природы.",
  "dnd.c.fighter": "Воин — мастер оружия и доспехов, обученный превосходить других в любом виде боя. Воины совершают дополнительные атаки, превосходят свои пределы благодаря Всплеску действий и переводят дух с помощью Второго дыхания. Солдаты, наёмники, рыцари и дуэлянты — всё это воплощения этого класса.",
  "dnd.c.monk": "Монах — мастер боевых искусств, направляющий внутреннюю энергию ци (в правилах 2024 года — фокус) на невероятные подвиги. Монахи с ослепительной скоростью бьют кулаками и простым оружием, отражают снаряды и передвигаются быстрее обычных людей. Их обучают в монастырях, следующих разным традициям.",
  "dnd.c.paladin": "Паладин — святой воин, связанный священной клятвой, которая и есть истинный источник его силы. Паладины сочетают бой в доспехах с божественной магией: исцеляют Наложением рук и вкладывают сияющую энергию в удары Божественной карой. Не храм, а клятва определяет идеалы, за которые они сражаются.",
  "dnd.c.ranger": "Следопыт — охотник и разведчик диких земель, сочетающий боевое мастерство с магией природы. Следопыты превосходно выслеживают добычу, выживают в глуши и сражаются луком или клинком, нередко изучая определённых врагов и местности. Они стерегут границы между цивилизацией и опасностями за её пределами.",
  "dnd.c.rogue": "Плут полагается на сноровку, скрытность и точность, а не на грубую силу. Плуты наносят сокрушительную Скрытую атаку, застав врага врасплох, ускользают с помощью Хитрого действия и владеют множеством навыков — от взлома замков до умения заговорить кому угодно зубы. Воры, шпионы, разведчики и убийцы — всё это плуты.",
  "dnd.c.sorcerer": "Чародей несёт магию в самой своей сути — чаще всего благодаря родословной или необычайному событию. Вместо изучения заклинаний чародеи направляют врождённую силу и преобразуют её Метамагией, тратя очки чародейства, чтобы изменить, продлить или ускорить свои чары. Происхождение их силы определяет особые дары.",
  "dnd.c.warlock": "Колдун получает магию благодаря договору с могущественным потусторонним покровителем. У колдунов мало ячеек заклинаний, но они восстанавливаются после короткого отдыха; у них есть фирменные заговоры вроде Мистического заряда и Таинственные воззвания, дающие необычные способности. Природа покровителя окрашивает и силы колдуна, и его характер.",
  "dnd.c.wizard": "Волшебник — учёный заклинатель, постигающий магию через обучение и записывающий заклинания в книгу заклинаний. Обладая самым обширным списком заклинаний среди всех классов, волшебник может подготовить подходящее заклинание почти для любой ситуации и вернуть часть потраченной магии Магическим восстановлением. Многие специализируются на одной школе магии.",
  "dnd.s.artificer.alchemist": "Алхимик — изобретатель, специализирующийся на сильнодействующих смесях. Он варит экспериментальные эликсиры с непредсказуемыми полезными эффектами, например исцелением, полётом или стойкостью, а алхимические знания усиливают его лечение и заклинания кислоты и огня. Позже он умеет излечивать недуги и восстанавливать много жизненных сил.",
  "dnd.s.artificer.armorer": "Бронник — изобретатель, превращающий доспех в магическую вторую кожу. Его волшебный доспех можно настроить на модель «Страж» с громовыми перчатками и защитным полем или на модель «Лазутчик» с молниеметом и усиленной скрытностью. С ростом мастерства доспех вмещает больше инфузий и становится мощнее.",
  "dnd.s.artificer.artillerist": "Артиллерист — изобретатель, специализирующийся на взрывной разрушительной магии. Его фирменное творение — мистическая пушка, небольшая магическая турель, которая обжигает врагов огнём, отбрасывает их силовой волной или защищает союзников. Он также направляет заклинания через магическое огнестрельное оружие, усиливая урон.",
  "dnd.s.artificer.battlesmith": "Боевой кузнец — изобретатель, сочетающий боевую доблесть с ремонтом и защитой. Он создаёт стального защитника — верного механического спутника, сражающегося рядом с ним, и может атаковать магическим оружием, используя Интеллект. Его магия тяготеет к лечению и защите союзников.",
  "dnd.s.barbarian.beast": "Путь зверя — путь варвара, чья ярость пробуждает внутреннюю звериную природу. Во время ярости варвар отращивает природное оружие — клыки, когти или хвост, позже обретает звериные приспособления для лазания, плавания и прыжков и может заражать врагов безумной яростью. Источником зверя может быть проклятие, происхождение или первобытный дух.",
  "dnd.s.barbarian.berserker": "Путь берсерка — путь варвара для тех, кто растворяется в чистом насилии. Его визитная карточка, Бешенство, позволяет наносить дополнительные удары во время ярости; позже варвар в ярости противостоит страху и очарованию и может устрашить врагов одним взглядом. Это самое прямое воплощение ярости.",
  "dnd.s.barbarian.stormherald": "Путь буревестника — путь варвара, чья ярость принимает облик первобытной бури. В ярости варвар излучает ауру, зависящую от выбранной стихии: жар пустыни, молнии моря или бодрящий холод тундры, дающий временные хиты. Буря также даёт сопротивление урону, а позже обрушивается на ближайших врагов.",
  "dnd.s.barbarian.wildheart": "Путь дикого сердца — путь варвара, версия Тотемного воителя из правил 2024 года, чья ярость связана с духами животных. Варвар черпает силу зверей вроде медведя, орла и волка ради стойкости, подвижности или слаженности и может общаться с животными. Его способности растут из родства с природой.",
  "dnd.s.bard.creation": "Коллегия созидания — коллегия бардов, вдохновлённая Песнью Творения, изначальной мелодией, которая, по преданию, сотворила мироздание. Такие барды усиливают союзников Нотами потенциала и способны песней создавать немагические предметы. На высоких уровнях они оживляют предмет, превращая его в танцующего спутника.",
  "dnd.s.bard.dance": "Коллегия танца — коллегия бардов из «Книги игрока» 2024 года, чьи участники выражают магию через движение. Их Ослепительная поступь превращает грациозные движения в защиту и безоружные удары, а сами они помогают союзникам перестраиваться и быстро действовать в бою. Позже они ловко уводят спутников от опасности.",
  "dnd.s.bard.eloquence": "Коллегия красноречия — коллегия бардов, посвящённая убеждению и риторике. Её барды почти никогда не терпят неудач в убеждении и обмане, подрывают решимость врага Тревожащими словами и вдохновляют союзников так умело, что их поддержка редко пропадает зря. На высоких уровнях их речь понятна любому существу.",
  "dnd.s.bard.glamour": "Коллегия очарования — коллегия бардов, уходящая корнями в чарующую магию Страны Фей. Такие барды окутывают союзников Мантией вдохновения, пленяют слушателей завораживающими выступлениями и могут принимать неземное величие, которому трудно не подчиниться. Их искусство заимствует изящество и обаяние фей.",
  "dnd.s.cleric.life": "Домен жизни — домен жрецов, посвящённый положительной энергии, поддерживающей всё живое. Его жрецы — сильнейшие целители: их заклинания лечат сильнее, а Сохранение жизни восстанавливает многих союзников разом. Чаще всего они служат богам исцеления, урожая и жизненной силы.",
  "dnd.s.cleric.tempest": "Домен бури — домен жрецов, принадлежащий богам гроз, моря и неба. Его жрецы повелевают громом и молнией, отвечают нападающим силой бури и с помощью Божественного канала наносят максимальный урон электричеством или звуком. Они часто носят тяжёлые доспехи и сражаются в первых рядах.",
  "dnd.s.cleric.trickery": "Домен обмана — домен жрецов, служащих богам озорства, воров и обмана. Его жрецы благословляют союзников скрытностью, создают иллюзорных двойников с помощью Призыва двойника и предпочитают заклинания иллюзий и отвлечения. Они действуют как хитрые агенты, подрывающие тиранию и гордыню.",
  "dnd.s.druid.dreams": "Круг снов — круг друидов, связанный со Страной Фей и миром сновидений. Его друиды исцеляют союзников Бальзамом Летнего двора, защищают свой лагерь охранной магией и ходят тайными тропами, позволяющими телепортироваться на короткие расстояния. Они хранят мягкие тайны фей.",
  "dnd.s.druid.land": "Круг земли — круг друидов-мистиков и мудрецов, оберегающих древние знания. Каждый друид черпает силу из выбранного типа местности, получая связанные с ним заклинания, и может восстанавливать потраченную магию во время отдыха. В правилах 2014 года есть такие местности, как арктика, пустыня, лес и горы, а в правилах 2024 года они сведены к засушливой, полярной, умеренной и тропической.",
  "dnd.s.druid.moon": "Круг луны — круг свирепых стражей, полагающихся в бою на Дикий облик. Они быстро превращаются в более сильных зверей, чем другие друиды, поддерживают себя в звериной форме и со временем принимают облик элементалей. Они охраняют дикие земли под переменчивой луной.",
  "dnd.s.druid.sea": "Круг моря — круг друидов из «Книги игрока» 2024 года, направляющий силу океанских приливов и штормов. Тратя Дикий облик, такие друиды окружают себя Гневом моря — аурой морских брызг, которая наносит урон холодом и отталкивает врагов. Позже они свободно плавают, летают на штормовых ветрах и сопротивляются холоду, молнии и звуку.",
  "dnd.s.fighter.battlemaster": "Мастер боевых искусств — архетип воина для тактиков, относящихся к бою как к науке. Они тратят кости превосходства на приёмы вроде обезоруживания, сбивания с ног или ободрения союзников и умеют оценить сильные стороны противника. Их мастерство основано на отточенной технике, а не на грубой силе.",
  "dnd.s.fighter.champion": "Чемпион — архетип воина, сосредоточенный на чистом физическом совершенстве. Чемпионы чаще наносят критические удары, становятся атлетичнее и со временем восстанавливают хиты каждый ход, когда тяжело ранены. Это самый простой и прямой путь воина.",
  "dnd.s.fighter.runeknight": "Рыцарь рун — архетип воина, владеющий рунной магией великанов. Он наносит магические руны на снаряжение ради разных эффектов и может вырасти до Большого размера с помощью Мощи великана, нанося дополнительный урон. С ростом силы рыцарь становится ещё крупнее и чаще пробуждает руны.",
  "dnd.s.monk.astral": "Путь астрального «я» — монашеская традиция, в которой ци принимает облик истинного «я» монаха, проецируемого с Астрального плана. Такие монахи призывают призрачные астральные руки, чтобы бить на большем расстоянии, а позже — астральный лик и целое тело, обостряющие чувства и защиту. Их практика — путь самопознания.",
  "dnd.s.monk.mercy": "Путь милосердия — монашеская традиция (в «Котле Таши» она называлась так же, а в правилах 2024 года стала «Воином милосердия»), чьи монахи управляют жизненной силой, чтобы лечить или ранить. Часто нося особую маску, они касанием залечивают раны и снимают недуги или наносят врагам дополнительный урон некротической энергией. Они ходят по грани между жизнью и смертью.",
  "dnd.s.monk.openhand": "Путь открытой ладони — монашеская традиция для мастеров безоружного боя (в правилах 2024 года — «Воин открытой ладони»). Их шквал ударов может сбить врага с ног, оттолкнуть его или лишить возможности реагировать, а Целостность тела позволяет им исцелять себя. На вершине обучения они постигают смертоносную Дрожащую ладонь.",
  "dnd.s.paladin.conquest": "Клятва покорения — клятва паладина для тех, кто ищет славы через победу и абсолютный порядок. Её паладины сеют страх на поле боя, а их аура карает испуганных врагов, ведь сила, по их убеждению, должна сокрушать хаос. Их заветы требуют гасить в противниках всякую надежду.",
  "dnd.s.paladin.devotion": "Клятва преданности — клятва паладина, воплощающая классические идеалы сияющего рыцаря: честность, храбрость, сострадание и долг. Её паладины заставляют оружие сиять святой силой благодаря Священному оружию, а их аура защищает союзников от очарования. Они стремятся быть маяками справедливости и добродетели.",
  "dnd.s.paladin.glory": "Клятва славы — клятва паладина для героев, уверенных, что им и их спутникам суждены великие деяния. Её паладины блистают в атлетике, вдохновляют союзников своими карающими ударами и придают им скорость своей аурой. Они неустанно тренируются, чтобы быть достойными легендарных героев, которыми восхищаются.",
  "dnd.s.paladin.vengeance": "Клятва мести — клятва паладина, посвящённая наказанию тех, кто творит тяжкое зло. Её паладины отмечают избранного врага Клятвой вражды, получая над ним преимущество, и неотступно преследуют добычу. Ради уничтожения зла они готовы поступиться собственной чистотой.",
  "dnd.s.ranger.beastmaster": "Повелитель зверей — архетип следопыта, связанного с животным-спутником. Следопыт и зверь сражаются как одна команда; в новых правилах спутник — первобытный зверь суши, моря или неба, которого следопыт призывает. С ростом опыта их взаимное доверие крепнет.",
  "dnd.s.ranger.gloomstalker": "Сумрачный охотник — архетип следопыта, чувствующего себя как дома в самых тёмных местах, например в Подземье. Он бьёт первым и сильнее всего в начале боя благодаря Ужасающему засадчику и становится почти невидим для существ, полагающихся на тёмное зрение. Его разум также закалён против страха и вторжения.",
  "dnd.s.ranger.hunter": "Охотник — архетип следопыта, стоящего между цивилизацией и ужасами дикой природы. Охотники выбирают особые приёмы против своей добычи — например, прорубаться сквозь орды, валить великанов или уклоняться от атак. Это разносторонние защитники, приспосабливающиеся к любой угрозе.",
  "dnd.s.rogue.arcanetrickster": "Мистический ловкач — архетип плута, добавляющий к скрытности и ловкости магию иллюзии и очарования. Невидимой Волшебной рукой он обчищает карманы и вскрывает замки на расстоянии, а позже с помощью заклинаний сбивает цели с толку и устраивает засады. Его магия служит искусству обмана.",
  "dnd.s.rogue.inquisitive": "Сыщик — архетип плута для детективов, раскрывающих тайны и ложь. Его острые чувства улавливают обман и скрытые детали, а внимательное наблюдение за противником помогает найти брешь для Скрытой атаки. Он превосходен в расследованиях, допросах и разгадке тайн.",
  "dnd.s.rogue.swashbuckler": "Дуэлянт — архетип плута для дерзких фехтовальщиков, полагающихся на скорость, изящество и обаяние. Он ускользает от врагов после атаки, может наносить Скрытую атаку в поединке один на один, а своей Бравадой очаровывает или провоцирует других. Это лихие герои приключенческих историй.",
  "dnd.s.sorcerer.aberrant": "Аберрантное чародейство — происхождение чародея, чья сила исходит от чуждого влияния: Дальнего Предела, иллитидов или странного псионического события. Такие чародеи говорят телепатически, изучают псионические заклинания, которые могут творить незаметно, и со временем пугающе изменяют своё тело. Впервые оно появилось как «Аберрантный разум» в «Котле Таши».",
  "dnd.s.sorcerer.draconic": "Драконья кровь — происхождение чародея, чья магия идёт от крови драконов. У таких чародеев от природы прочная чешуйчатая кожа, они усиливают заклинания стихии своего драконьего предка, а со временем отращивают драконьи крылья и излучают ауру благоговения. Их характер часто отражает драконью гордость.",
  "dnd.s.sorcerer.storm": "Штормовое колдовство — происхождение чародея, питаемое стихийным воздухом. Таких чародеев окутывают ветер и молнии, при сотворении заклинаний они могут немного пролететь, а позже обретают сопротивление молнии и звуку и подчиняют себе погоду. Их силу часто связывают с великой бурей или Стихийным планом Воздуха.",
  "dnd.s.sorcerer.wildmagic": "Дикая магия — происхождение чародея, чья сила исходит от хаотичных сил первозданной магии. Сотворение заклинаний может вызвать непредсказуемый Всплеск дикой магии, полезный или причудливый, а Поток хаоса позволяет таким чародеям склонять удачу на свою сторону. Их магия захватывает, но никогда не бывает полностью под контролем.",
  "dnd.s.warlock.archfey": "Архифея — покровитель колдуна, связывающий его с могущественным повелителем или повелительницей фей. Такие колдуны очаровывают или пугают других и ускользают от опасности туманными телепортирующими шагами. Их покровители — своенравные существа Страны Фей с чуждыми чувствами и прихотями.",
  "dnd.s.warlock.celestial": "Небожитель — покровитель колдуна, связывающий его с существом Верхних планов, например эмпиреем или единорогом. Такие колдуны лечат Целительным светом, наносят урон излучением и огнём, а позже могут подняться с порога смерти. Их сила напоминает силу жреца, но исходит из личной связи.",
  "dnd.s.warlock.fiend": "Исчадие — покровитель колдуна, предлагающий договор с существом Нижних планов, например повелителем демонов или архидьяволом. Такие колдуны получают временные хиты, сражая врагов, призывают тёмную удачу и становятся стойкими к урону. Подобные сделки опасны и никогда не бывают по-настоящему бесплатными.",
  "dnd.s.warlock.greatoldone": "Великий Древний — покровитель колдуна, чья сила исходит от непостижимой сущности далеко за пределами планов. Такие колдуны обретают телепатию, защищают свои мысли и могут подчинять чужой разум. Покровитель может даже не знать об их существовании, даруя запретное знание, а не наставления.",
  "dnd.s.wizard.enchantment": "Школа очарования — традиция волшебников, специализирующихся на магии, влияющей на разум и поведение. Такие волшебники могут заворожить врага взглядом, перенаправлять атаки, а позже изменять воспоминания очарованных. Они считают, что убеждение и контроль способны разрешать конфликты без кровопролития.",
  "dnd.s.wizard.illusion": "Школа иллюзии — традиция волшебников, специализирующихся на обманной магии, которая вводит в заблуждение чувства. Их иллюзии особенно убедительны, их можно изменять после сотворения, и они даже способны становиться отчасти реальными. Такие волшебники также защищают себя иллюзорными двойниками, сбивающими нападающих с толку.",
  "dnd.s.wizard.transmutation": "Школа преобразования — традиция волшебников, специализирующихся на магии, изменяющей материю и энергию. Такие волшебники могут временно превращать один материал в другой, создавать камень преобразования с разными свойствами и менять собственный облик. На вершине мастерства они творят чудесные превращения.",
  "dnd.al.CE": "Хаотично-злой персонаж творит произвольное насилие, движимый жадностью, ненавистью или жаждой крови. Он отвергает порядок, а такие существа обычно держатся вместе только из страха перед более сильным вожаком. Классические примеры из «Книги игрока» — демоны Бездны и красные драконы.",
  "dnd.al.CG": "Хаотично-добрый персонаж следует своей совести, мало заботясь о чужих ожиданиях. Он ценит свободу и доброту и не доверяет правилам, которые мешают творить добро. В «Книге игрока» примерами служат медные драконы, многие эльфы и единороги.",
  "dnd.al.CN": "Хаотично-нейтральный персонаж следует своим прихотям и превыше всего ценит личную свободу. Им движет не злоба и не альтруизм, а независимость. По «Книге игрока», к этому мировоззрению склонны многие варвары и плуты, а также некоторые барды.",
  "dnd.al.LE": "Законно-злой персонаж методично берёт то, что хочет, в рамках кодекса, традиции или иерархии. Он соблюдает договоры и верность — пока это ему выгодно. Типичный пример — дьяволы Девяти Преисподних, а также тираны и интриганы-чиновники.",
  "dnd.al.LG": "Законно-добрый персонаж старается поступать правильно так, как этого ждёт общество: держит слово, уважает законную власть и защищает невинных. Классический образ — паладины и благородные рыцари. Типичная слабость этого мировоззрения — негибкость, когда правила путают с самим добром.",
  "dnd.al.LN": "Законно-нейтральный персонаж действует по закону, традиции или личному кодексу, а не из доброты или жестокости. Ценность для него — сам порядок. Под это мировоззрение подходят судьи, дисциплинированные солдаты и многие монахи.",
  "dnd.al.NE": "Нейтрально-злой персонаж делает всё, что сойдёт ему с рук, исключительно ради собственной выгоды, без верности закону и без любви к хаосу. Это эгоизм в чистом виде. Архетипичные нейтрально-злые существа — юголоты, исчадия-наёмники.",
  "dnd.al.NG": "Нейтрально-добрый персонаж делает столько добра, сколько может, не отдавая особого предпочтения ни правилам, ни их нарушению. Он помогает там, где нужна помощь, действуя вместе с властью или в обход неё — по обстоятельствам. В «Книге игрока» нейтрально-добрыми названы многие небожители и большинство гномов.",
  "dnd.al.NN": "Истинно нейтральный персонаж держится подальше от моральных крайностей: либо избегает трудного выбора, либо сознательно стремится к равновесию. Некоторые друиды видят в нейтралитете гармонию с природным порядком. «Книга игрока» относит к нейтральным большинство друидов и многих людей.",
  "dnd.r.changeling": "Чейнджлинги — оборотни, способные по желанию менять внешность и голос, примеряя новое лицо когда захотят. Они пришли из сеттинга Эберрон, а позже появились в книге «Морденкайнен представляет: Монстры Мультивселенной». Их истинный облик бледен, с бесцветными глазами, и многие чейнджлинги держат несколько личин для разных ситуаций.",
  "dnd.r.dragonborn": "Драконорождённые — гордые гуманоиды драконьего происхождения, с чешуёй и драконьими головами. Каждый связан с определённым видом драконов, который задаёт тип урона его дыхательного оружия и его сопротивление: кислота, холод, огонь, молния или яд. Клан и честь для них очень важны, а в Забытых Королевствах они связаны со страной Тимантер.",
  "dnd.r.drow": "Дроу — тёмные эльфы Подземья, огромного мира под поверхностью. Традиционно они живут в матриархальных городах вроде Мензоберранзана, где правят жрицы богини-паучихи Ллос. У них превосходное тёмное зрение и врождённая магия, например «огонь фей» и «тьма». Самый знаменитый дроу — Дзирт До'Урден, покинувший свой народ ради поверхности.",
  "dnd.r.dwarf": "Дварфы — крепкий и долгоживущий народ, славный своими рудокопами, кузнецами и залами, высеченными в горах. Они выносливы, устойчивы к ядам и видят в темноте. В их культуре огромную роль играют клан, предки и старые обиды, а во главе дварфийского пантеона стоит Морадин, Создатель Душ.",
  "dnd.r.elf": "Эльфы — изящный долгоживущий народ, глубоко связанный с магией и Страной Фей. Вместо сна они на несколько часов погружаются в медитативный транс. Наследие фей помогает им противостоять очарованию. Существует много эльфийских линий, включая высших эльфов, лесных эльфов и дроу.",
  "dnd.r.goliath": "Голиафы — народ великанского роста, родственный великанам и традиционно живущий высоко в горах. В «Книге игрока» 2024 года у каждого голиафа есть великанье происхождение, дающее сверхъестественный дар — например, силу огня, мороза или бури, — и способность ненадолго вырасти до Большого размера. Их культура ценит честное соперничество и личные достижения.",
  "dnd.r.halfling": "Полурослики — маленький жизнерадостный народ, который дорожит домом, вкусной едой и дружными общинами. Они славятся своей удачей, позволяющей перебросить выпавшую «1». Они храбры не по росту и достаточно ловки, чтобы проскользнуть мимо существ крупнее. Многие живут в тихих собственных деревнях или среди людей.",
  "dnd.r.halforc": "Полуорки сочетают человеческое и оркское наследие и были играбельной расой в «Книге игрока» 2014 года. Они известны силой и выносливостью: получив смертельный удар, полуорк может стиснуть зубы и остаться на ногах с 1 хитом. Их свирепые атаки наносят дополнительный урон при критическом попадании. В правилах 2024 года их место занял вид «орк».",
  "dnd.r.human": "Люди — самый распространённый и разнообразный народ в большинстве миров D&D. Их жизнь коротка по сравнению с эльфами или дварфами, и это толкает их к честолюбию и быстрым свершениям. В правилах 2024 года они известны находчивостью и разносторонностью: получают Героическое вдохновение после каждого долгого отдыха и дополнительный навык.",
  "dnd.r.kenku": "Кенку — нелетающий птичий народ, похожий на ворон. Они славятся подражанием, воспроизводя звуки и голоса, которые когда-либо слышали. У них также цепкая память на детали. Старые предания гласят, что они лишились крыльев и собственных голосов в наказание за древнее предательство.",
  "dnd.r.tabaxi": "Табакси — кошачьи гуманоиды, которые в Забытых Королевствах происходят из далёкой земли Мацтика. Ими движет любопытство: они обожают собирать истории, вещи и впечатления. Когти помогают им лазать, кошачья ловкость позволяет делать короткие рывки, а в полумраке они видят хорошо.",
  "dnd.r.tiefling": "Тифлинги несут в крови наследие исчадий, которое часто проявляется в рогах, хвосте и необычном цвете кожи или глаз. В Забытых Королевствах многие возводят это наследие к Асмодею, владыке Девяти Преисподних. Правила 2024 года предлагают бездновое, хтоническое и инфернальное наследие, каждое со своим сопротивлением и врождёнными заклинаниями. Им часто не доверяют, но происхождение не определяет их характер.",
  "dnd.r.yuanti": "Юань-ти — змеиный народ, потомки людей, изменённых древними ритуалами в честь змеиных богов. Когда-то их империи господствовали в джунглях, и многие юань-ти до сих пор мечтают их возродить. Как персонажи игроков в «Монстрах Мультивселенной» они устойчивы к магии и яду и обладают врождённой магией, способной очаровывать змей.",
  "wi.g.aard": "Аард — знак, высвобождающий телекинетический удар, который отбрасывает, сбивает с ног или оглушает противников. Ведьмаки также используют его, чтобы ломать стены, двери и другие препятствия. В играх это один из пяти основных знаков, а улучшенные формы могут поражать врагов вокруг ведьмака.",
  "wi.g.axii": "Аксий — знак, воздействующий на разум: он успокаивает, сбивает с толку или подчиняет цель. В книгах Геральт применяет его, чтобы утихомирить животных или ненадолго подчинить волю человека. В играх он может заставить врага прекратить бой или даже обратиться против союзников, а также открывает дополнительные варианты в диалогах.",
  "wi.g.igni": "Игни — знак, выпускающий поток огня, который обжигает врагов и поджигает предметы. Он особенно эффективен против существ, уязвимых к пламени. В «Ведьмаке 3» его продвинутая форма создаёт непрерывную струю огня.",
  "wi.g.quen": "Квен — защитный знак, окружающий ведьмака магическим щитом, который поглощает урон. Это стандартная защита ведьмака в опасных схватках. В «Ведьмаке 3» альтернативная форма создаёт активный щит, который восстанавливает здоровье ведьмака, пока поглощает удары.",
  "wi.g.yrden": "Ирден — знак, начертывающий на земле магический глиф, который замедляет вошедших в него врагов. Он незаменим против призраков и других бесплотных существ: внутри круга они становятся осязаемыми. В «Ведьмаке 3» альтернативная форма превращает его в магическую ловушку, поражающую ближайших врагов.",
  "wi.s.bear": "Школа Медведя известна тяжёлыми доспехами и могучими, выносливыми ведьмаками, способными выдержать огромный урон. Её крепость называется Хаэрн Кадух. Ведьмаки-медведи славились тем, что жили обособленно, и мрачным, нелюдимым нравом.",
  "wi.s.cat": "Школа Кота воспитывала ловких и быстрых бойцов в лёгких доспехах, ставивших скорость выше защиты. У её ведьмаков мрачная репутация: многие брались за работу наёмных убийц или наёмников. Некоторые источники описывают школу как не имеющую постоянной крепости и кочующую с места на место. Гаэтан из «Ведьмака 3» — один из её представителей.",
  "wi.s.griffin": "Школа Грифона уделяет знакам больше внимания, чем другие школы, а её ведьмаки известны рыцарским кодексом поведения. Её крепость, Каэр Серен, стояла на побережье. Там обучался Коэн, друг Геральта из книг. Снаряжение школы в «Ведьмаке 3» — средние доспехи, подходящие для стиля с упором на знаки.",
  "wi.s.manticore": "Школа Мантикоры — одна из малоизвестных ведьмачьих школ, упоминаемая в основном в дополнительных материалах, например в настольной ролевой игре. О её крепости, членах и методах в каноне известно немного, поэтому описания в разных источниках расходятся. Как и другие школы, она названа в честь грозного чудовища.",
  "wi.s.viper": "Школа Змеи связана с южными землями и с Нильфгаардской империей. Её самый известный представитель — Лето из Гулеты, Убийца королей из «Ведьмака 2». Её крепость называется Гортур Гваэд, а её ведьмаков связывают с ядами и лёгким, подвижным снаряжением.",
  "wi.s.wolf": "Школа Волка обучала ведьмаков в Каэр Морхене — крепости в Синих горах Каэдвена. Это школа Геральта из Ривии, а также Весемира, Эскеля и Ламберта. Давным-давно на крепость напали, и после этого в живых осталась лишь горстка ведьмаков. Ведьмаки-волки сочетают фехтование, знаки и алхимию.",
  "av.e.water": "Вода — стихия перемен. Магией воды владеют в основном жители Северного и Южного племён Воды; они научились ей у Луны и у приливов и отливов океана. Сила магов воды растёт в полнолуние и слабеет в новолуние. Магия воды включает продвинутые техники: целительство, управление растениями и магию крови.",
  "av.e.earth": "Земля — стихия основательности. Маги земли, чаще всего живущие в Царстве Земли, научились у барсукокротов — первых магов земли. Их стиль строится на том, чтобы стоять твёрдо и ждать подходящего момента для удара. К её особым техникам относятся управление металлом, песком и лавой.",
  "av.e.fire": "Огонь — стихия силы. Маги огня, в основном выходцы из Народа Огня, изначально учились у драконов, а их сила исходит из дыхания и внутренней энергии. Магия огня крепнет под солнцем и исчезает во время солнечного затмения. К её продвинутым формам относятся молнии и взрывы силой мысли.",
  "av.e.air": "Воздух — стихия свободы. Маги воздуха учились у летающих бизонов и жили как Воздушные кочевники в четырёх храмах. После нападения Народа Огня на кочевников Аанг остался последним магом воздуха, пока после Гармонического сближения не появились новые. Магия воздуха уклончива и оборонительна, она построена на круговых движениях.",
  "av.t.vines": "Лозы — техника магии воды, позволяющая управлять водой внутри растений и двигать лозы, корни и другую растительность. Её разработало Племя Туманного болота. Она показывает, что магия воды может работать с живыми существами, а не только с открытой водой.",
  "av.t.sand": "Песок — особая техника магии земли для управления рыхлым песком. Её развили песочные маги пустыни Си Вонг, которые с её помощью гоняют песчаные парусники по дюнам и поднимают песчаные бури. Она требует более тонкого контроля, чем обычная магия земли.",
  "av.t.healing": "Целительство — навык магии воды, при котором маг ведёт воду по энергетическим путям тела, залечивая раны и унимая боль. Катара — одарённая целительница. Вода из Оазиса духов на Северном полюсе обладает особой целебной силой: именно ею Катара спасла Аанга.",
  "av.t.metal": "Металл — техника магии земли, изобретённая Тоф Бейфонг: она почувствовала частицы земли внутри металла и научилась им управлять. Очень чистые металлы, например платину, подчинить нельзя. Ко времени «Легенды о Корре» эта техника широко распространилась: ею пользуются полиция Республиканского города и металлический клан Заофу.",
  "av.t.lightning": "Молния — продвинутый навык магии огня, который иногда называют «хладнокровным огнём»: маг разделяет положительную и отрицательную энергию и даёт им снова столкнуться. Им владели Азула, Озай и Айро. Айро также создал технику перенаправления молнии через энергетические пути тела.",
  "av.t.blood": "Магия крови — техника магии воды, позволяющая управлять водой внутри живого тела и подчинять движения цели. Хама разработала её в плену у Народа Огня и применяла в полнолуние. Позже эту технику запретили; в «Легенде о Корре» Якон и его сыновья владели ею даже без полнолуния.",
  "av.t.lava": "Лава — редкая техника магии земли, позволяющая превращать камень в расплавленную лаву и обратно. В «Легенде о Корре» ею овладели Газан из Красного Лотоса, а позже Болин. Некоторые Аватары, например Року, тоже владели ею.",
  "av.t.combustion": "Взрыв — редкая техника магии огня, при которой маг создаёт взрывы, фокусируя энергию силой мысли. У её носителей обычно есть татуировка третьего глаза на лбу. Самые известные её мастера — Человек-взрыв (Комбастион-мэн) и Пи'Ли из Красного Лотоса.",
  "av.t.spirit": "Духовная энергия — древнейшая форма магии, существовавшая ещё до того, как люди овладели четырьмя стихиями. Львиные черепахи с её помощью наделяли людей силой стихий. Аанг с её помощью лишил Озая магии огня, а позже она сыграла роль в том, что Корра вернула магию другим.",
  "av.avatar": "Аватар — повелитель всех четырёх стихий и мост между миром людей и Миром духов. Цикл начался с Вана, который слился с Раавой — духом света и мира. Когда Аватар умирает, он перерождается в следующем народе цикла: Огонь, Воздух, Вода, Земля. В состоянии Аватара он может черпать силу и знания из своих прошлых жизней.",
  "wod.aus.ahroun": "Арун — гару, рождённые под полной луной, воины Нации Гару. Их Ярость горит жарче, чем у любого другого прорицания, и от них ждут, что они встанут в первый ряд против Змия и его слуг. Их Дары служат битве, стойкости и командованию в бою. Многие из них гибнут в сражениях, а выжившие несут память о каждом потерянном товарище по стае.",
  "wod.aus.galliard": "Галлиард — гару, рождённые под растущей луной, лунные танцоры своего народа: сказители, поэты и хранители устной истории. Они сберегают легенды племени, ведут великий вой на сходах и воодушевляют стаю перед боем. Их Дары связаны с общением, чувствами и снами. Страстные по натуре, они так же легко впадают в веселье, как и в гнев.",
  "wod.aus.philodox": "Филодокс — гару, рождённые под половинной луной, в равновесии между светом и тьмой; они судьи и хранители закона среди гару. Они знают Литанию наизусть, разрешают споры, следят за поединками и оценивают притязания на Славу. Их Дары помогают распознавать правду и читать намерения других. Их уважают, а порой и недолюбливают, ведь беспристрастными они обязаны оставаться даже тогда, когда дело касается их собственной стаи.",
  "wod.aus.ragabash": "Рагабаш — гару, рождённые под новой луной, трикстеры и вопрошающие Нации Гару. Их священный долг — бросать вызов традициям, обличать лицемерие и не давать старейшинам успокоиться, нередко с помощью проделок. Их Дары служат скрытности, хитрости и обману. Ярости у них меньше, чем у любого другого прорицания, но их ценят как разведчиков и как голос, задающий неудобные вопросы.",
  "wod.aus.theurge": "Теург — гару, рождённые под серпом луны, провидцы и собеседники духов. Они общаются с духами Умбры, заключают их в фетиши и проводят многие обряды. Гнозис у них высок, а Дары тяготеют к мистическому. Их часто считают странными и отстранёнными, но без них не выжить ни одной стае.",
  "wod.breed.homid": "Хомид — гару, рождённые от людей и выросшие среди людей; обычно они не подозревают о своём наследии до Первого Изменения. Сегодня это самая многочисленная порода, и в человеческом обществе и технологиях они разбираются куда лучше сородичей. Их естественная форма — человеческая, и Гнозиса у них изначально меньше всего. Некоторые гару, прежде всего Красные Когти, относятся к ним с подозрением.",
  "wod.breed.lupus": "Люпус — гару, рождённые от волков и живущие в волчьей стае до Первого Изменения. Их естественная форма — волк, а связь с Геей и миром духов у них самая тесная, что отражается в высоком Гнозисе. Человеческие понятия вроде денег, письменности или часов часто ставят их в тупик. С исчезновением диких волков редеет и эта порода.",
  "wod.breed.metis": "Эти гару рождены от союза двух оборотней — союза, запрещённого Литанией. Они появляются на свет в форме Криноса, боевом облике, не могут иметь собственного потомства, и каждый несёт телесное уродство, выдающее его происхождение. Их долго считали изгоями и позором, однако они вырастают внутри септа и нередко знают общество гару и Умбру лучше всех. Их естественная форма — Кринос.",
  "wod.gen": "Поколение показывает, сколько Становлений отделяет вампира от Каина, первого из Сородичей. Чем ниже поколение, тем сильнее кровь: она позволяет иметь более высокие Характеристики, больший запас крови и тратить больше крови за ход. Недавно Обращённые неонаты обычно принадлежат к двенадцатому или тринадцатому поколению, а Допотопные третьего поколения почти легендарны. Диаблери — поглощение души вампира более низкого поколения — единственный способ понизить своё собственное.",
  "wod.gnosis": "Гнозис — духовная связь гару с Геей и Умброй. Он питает многие Дары, позволяет оборотню шагнуть в мир духов и необходим, чтобы пробудить фетиши и талены. Больше всего Гнозиса обычно у люпусов и теургов. Гнозис и Ярость тянут в разные стороны: гнев мешает духовной сосредоточенности.",
  "wod.path.accord": "Путь Соглашения Чести — Путь Просветления Шабаша, основанный на рыцарстве, верности и данном слове. Его последователи, Рыцари, верят, что честь и долг перед сектой, стаей и вождями удерживают Зверя в узде. Он популярен среди воинов и стражей секты. Нарушить клятву или предать товарища — тягчайший из грехов.",
  "wod.path.blood": "Путь Крови — традиционный моральный кодекс Ассамитов, восходящий к учению их основателя Хакима. Его последователи считают прочих Сородичей проклятыми и верят, что их кровь, особенно добытая через диаблери, приближает их к Хакиму. Путь требует дисциплины, верности клану и суда над недостойными потомками Каина.",
  "wod.path.caine": "Путь Каина — учение нодистов, изучающих легенды о первом вампире, сохранённые в Книге Нод. Его последователи видят в вампиризме не проклятие, от которого нужно бежать, а состояние, которое следует понять и подчинить, и берут Каина за образец. Это учёные, спорщики и искатели древних знаний; диаблери и осознанное использование Зверя они считают допустимыми инструментами. Больше всего этот Путь распространён в Шабаше.",
  "wod.path.cathari": "Путь Катари восходит к средневековой ереси катаров, учившей, что материальный мир — творение зла. Его последователи считают себя проклятыми духами, чьё предназначение — воплощать потакание страстям и искушение, и открыто предаются страсти и излишествам вместо того, чтобы их сдерживать. При этом у них есть собственный кодекс: они тщательно выбирают, кого искушать и кого Обращать.",
  "wod.path.feral": "Путь Дикого Сердца учит, что вампиры — хищники, а Зверь — естественная их часть, а не враг. Его последователи живут инстинктами охотника: убивают, когда голодны, защищают свою территорию и избегают бессмысленной жестокости. Он особенно популярен среди Гангрел и других Сородичей, близких к дикой природе, и связан с Шабашем.",
  "wod.path.humanity": "Человечность — моральный ориентир, за который держится большинство Сородичей, мера того, сколько смертной совести пережило Становление. Она следует обычной человеческой этике: не убивать, не красть, уважать других. Когда Человечность падает, вампир становится холоднее, чудовищнее и уязвимее перед Зверем. Ей следует большинство вампиров Камарильи, тогда как многие в Шабаше отвергают её ради Пути Просветления.",
  "wod.path.lilith": "Путь Лилит — учение бахари, почитающих Лилит, первую жену Каина, которая, согласно их легендам, открыла ему тайны ночи. Они верят, что боль — великий учитель, а страдание приносит рост и мудрость. Их обряды мистичны и скрытны, и многие Сородичи считают их опасными еретиками, противоречащими Книге Нод.",
  "wod.path.metamorph": "Путь Метаморфоз принадлежит прежде всего Цимисхам, особенно их старейшинам и учёным. Его последователи считают вампиризм ступенью преображения, которую нужно превзойти, и с помощью Дисциплины Изменчивости перекраивают свои тела и изучают природу Сородичей. Чувства для них — пустая помеха; они стремятся к знанию, не потакая ни другим, ни себе.",
  "wod.path.night": "Путь Ночи, созданный Ласомбра, учит, что вампиры прокляты Богом и их роль — быть тьмой, испытывающей человечество. Его последователи, нигилисты, сеют страх среди смертных, чтобы спасение обрели лишь истинно верующие. Они видят себя орудиями божественного замысла, а не просто чудовищами. Путём Ночи следуют в основном Ласомбра и другие члены Шабаша.",
  "wod.path.paradox": "Путь Парадокса — традиционное учение клана Равнос, опирающееся на индийские понятия сансары и свадхармы. Его последователи верят, что вампиры выпали из круговорота перерождений и их долг — пронзать иллюзию и восстанавливать должный ход мироздания, порой устраняя тех, кто ему мешает. За пределами клана этот Путь почти неизвестен.",
  "wod.path.power": "Путь Власти и Внутреннего Голоса — учение объединителей, верящих, что просветление достигается через власть над собой и накопление могущества в мире. Это честолюбивые политики и стратеги Шабаша, ставящие результат выше чувств и использующие страх и боль как инструменты контроля. Милосердие и неудача одинаково считаются слабостью. Этим Путём идут многие Ласомбра и вожди Шабаша.",
  "wod.path.scorched": "Путь Выжженного Сердца, чьих последователей называют Непрощающими, учит, что эмоции — орудия Зверя и их нужно погасить холодным разумом. Он связан с Истинными Бруха и с тайной организацией Таль'Махе'Ра. Его приверженцы отвергают мораль как порождение чувств, но соблюдают строгий этический кодекс, ставят факты выше мнений и используют других, когда это выгодно.",
  "wod.path.self": "Путь Внутреннего Фокуса — учение интерналистов, связанное с тайной организацией Таль'Махе'Ра. Опираясь на азиатские духовные традиции, он учит, что изменить мир невозможно — можно изменить лишь себя. Его последователи не вмешиваются в чужие дела, регулярно медитируют, живут настоящим и стремятся к власти над собой, чтобы держать Зверя в узде.",
  "wod.path.typhon": "Путь Тифона — ортодоксальная вера Последователей Сета. Его приверженцы, теофидианы, верят, что Сет — бог, который однажды вернётся, и стремятся освободить смертных и Сородичей от оков условностей, совести и веры через искушение и развращение. Они постигают тайны Сета и считают помощь в его воскрешении высшим долгом.",
  "wod.rage": "Ярость — гнев воинов Геи, жгучая злость, питающая силу гару в бою. Она позволяет оборотню действовать со сверхъестественной быстротой, мгновенно менять облик и сражаться, несмотря на раны, но она и опасна: избыток Ярости ввергает гару в бешенство и тревожит людей и животных. Больше всего Ярости у арунов, меньше всего — у рагабашей.",
  "wod.rank.adren": "Адрен — третий ранг в обществе гару, которого достигают те, кто накопил великую Славу. Адрены — опытные ветераны, нередко вожаки стай или должностные лица септа, и их слово весомо на сходах. От них ждут, что они будут учить и направлять младших по рангу.",
  "wod.rank.athro": "Атро — четвёртый ранг, которого достигают сравнительно немногие гару. Атро — прославленные герои, чьи деяния воспевают в песнях племени; они часто занимают важные должности в септе, например стража каэрна или мастера обрядов. Их суждения пользуются широким уважением.",
  "wod.rank.cliath": "Клиат — первый настоящий ранг в обществе гару, который получают, пройдя Обряд Посвящения. Клиата признают полноправным членом племени, но ему ещё предстоит доказать себя; большинство новых персонажей начинают именно здесь. Они зарабатывают Славу, исполняя долг своего прорицания, и должны прислушиваться к наставлениям старших.",
  "wod.rank.elder": "Старейшина — пятый ранг, высший из обычно достижимых в обществе гару. Старейшины — легендарные фигуры, которые ведут септы и племена и определяют путь Нации Гару; их слово имеет огромный вес. Этого ранга достигает лишь горстка гару.",
  "wod.rank.fostern": "Фостерн — второй ранг гару, который получают те, чьи деяния принесли достаточно Славы, чтобы доказать свою ценность. За плечами у фостернов уже есть опыт, и им доверяют более важные задачи, например вести стаю на задание. Это уважаемые воины и охотники, но ещё не вожди септа.",
  "wod.sect.cam": "Камарилья — крупнейшая секта Сородичей, общество, которое утверждает, что говорит от имени всех вампиров. В её основе лежит Маскарад — традиция скрывать существование вампиров от смертных, — а также прочие Традиции, за соблюдением которых в каждом городе следит Князь. Её опору составляют Вентру, Тореадор, Тремеры, Носферату, Малкавианы и Бруха. Она ценит порядок, стабильность и власть старейшин.",
  "wod.sect.sab": "Шабаш — секта вампиров, отвергающая смирение Маскарада и власть Допотопных и считающая Сородичей выше человечества. Его члены объединяются в стаи, скреплённые Вальдери — общим ритуалом крови, который заменяет личные узы крови верностью секте. Под предводительством Ласомбра и Цимисхов Шабаш ведёт войну с Камарильей и готовится к возвращению Допотопных. Многие его члены следуют Путям Просветления вместо Человечности.",
  "wod.vamp.assamite": "Ассамиты — клан убийц, воинов и учёных с Ближнего Востока, потомки Хакима. Их клановые Дисциплины — Стремительность, Затемнение и Квиетус, искусство смертоносной крови. Они издавна славятся тем, что берут заказы на жизни других Сородичей, часто с оплатой витэ, и когда-то страдали от проклятия Тремеров, ограничивавшего их диаблери. Клан делится на касты воинов, визирей и колдунов и стоит в стороне от больших сект.",
  "wod.vamp.brujah": "Бруха когда-то были царями-философами древнего Карфагена; сегодня их знают как бунтарей, идеалистов и смутьянов. Их Дисциплины — Стремительность, Могущество и Присутствие. Их страстность легендарна и делает их склонными к бешенству. Большинство состоит в Камарилье, оставаясь её самыми беспокойными членами; другие примыкают к анархам или Шабашу.",
  "wod.vamp.gangrel": "Гангрел — странники, которым в глуши уютнее, чем в городах. Их Дисциплины — Анимализм, Стойкость и Протеан, позволяющий отращивать когти, уходить в землю и принимать облик животных. Каждое бешенство может оставить им стойкую звериную черту. Независимые по натуре, они отдалились от Камарильи, и многие держатся рядом с анархами или Шабашем.",
  "wod.vamp.giovanni": "Джованни — семейный клан венецианских купцов и некромантов. Их Дисциплины — Доминирование, Некромантия и Могущество. Они Обращают в основном членов своего рода, владеют огромным богатством в мире смертных и повелевают духами мёртвых. Своё положение они обрели, совершив диаблери над собственным Допотопным, и теперь стоят особняком, связанные старым договором с Камарильей не вмешиваться в чужие дела.",
  "wod.vamp.lasombra": "Ласомбра — гордые аристократы тени и вожди Шабаша. Их Дисциплины — Доминирование, Обтенебрация и Могущество; Обтенебрация позволяет повелевать живой тьмой. Они не отражаются в зеркалах. Многие тесно связаны с Церковью, и они превыше всего ценят честолюбие, совершенство и лидерство.",
  "wod.vamp.malkavian": "Малкавианы — безумцы среди Сородичей: каждый член клана с момента Становления несёт в себе психическое расстройство. Их Дисциплины — Ауспекс, Деменция и Затемнение, хотя некоторые линии владеют Доминированием вместо Деменции. Безумие дарует им странные озарения и особое восприятие истины, и многие верят, что их объединяет скрытая связь — Сеть Безумия Малкавиан. Большинство состоит в Камарилье, а часть служит Шабашу.",
  "wod.vamp.nosferatu": "Носферату чудовищно обезображены Становлением и вынуждены скрывать свои лица от смертных. Их Дисциплины — Анимализм, Затемнение и Могущество. Они обустраивают убежища в канализации и туннелях под городами и считаются лучшими торговцами информацией среди Сородичей. Несмотря на внешность, они часто верны и практичны; большинство из них состоит в Камарилье.",
  "wod.vamp.setite": "Последователи Сета — клан египетского происхождения, поклоняющийся своему Допотопному, Сету, как богу. Их Дисциплины — Затемнение, Присутствие и Серпентис, дарующий им змеиные черты. Их знают как искусителей и торговцев пороками и тайнами, верящих, что развращение освобождает души от оков. Они не принадлежат ни к одной секте, и прочие Сородичи им не доверяют.",
  "wod.vamp.toreador": "Тореадор — художники, эстеты и ценители красоты. Их Дисциплины — Ауспекс, Стремительность и Присутствие. Они занимают видное место в Камарилье, где определяют жизнь Элизиума и культурную жизнь города. Любовь к красоте — и их слабость: нечто по-настоящему прекрасное способно заворожить их настолько, что они забывают обо всём остальном.",
  "wod.vamp.tremere": "Тремеры были смертными магами, захватившими бессмертие с помощью магии крови. Их Дисциплины — Ауспекс, Доминирование и Тауматургия. Они строго организованы в Пирамиду с центром в Вене, а члены клана связаны со старейшинами узами крови. Они — опора Камарильи: их ценят за чародейство, но не доверяют из-за их честолюбия.",
  "wod.vamp.tzimisce": "Цимисхи — аристократы старого мира из Восточной Европы, учёные и мастера плоти. Их Дисциплины — Анимализм, Ауспекс и Изменчивость, позволяющая лепить плоть и кость. Отдыхать они должны в земле своей родины. Вместе с Ласомбра они возглавляют Шабаш, и многие из них следуют Пути Метаморфоз.",
  "wod.vamp.ventrue": "Вентру — клан королей, аристократы и вожди Камарильи. Их Дисциплины — Доминирование, Стойкость и Присутствие. Они считают себя хранителями общества Сородичей и часто носят титул Князя. Их слабость — разборчивость: каждый Вентру может питаться кровью лишь одного определённого типа смертных.",
  "wod.wolf.fangs": "Серебряные Клыки — традиционные вожди Нации Гару, племя благородного происхождения, превыше всего ценящее чистоту крови. Они веками правили гару, почитая честь, чистоту и благородство. Однако поколения близкородственных союзов оставили многим из них психические расстройства, и их власть оспаривается всё сильнее. Их Дары служат лидерству, достоинству и вдохновению других.",
  "wod.wolf.fenris": "Потомство Фенрира — свирепые воины скандинавского и германского происхождения, живущие ради битвы со Змием. Они ценят силу, отвагу и славу и считают слабость пороком. Их Дары служат бою, выносливости и устрашению. Их уважают за доблесть, но и критикуют за жестокость и нетерпимость.",
  "wod.wolf.fianna": "Фианна — кельтские гару, барды и сказители Нации. Они славятся своей страстностью, любовью к песням и выпивке и глубокой связью с феями. Их Дары служат песне, иллюзии и миру фей. Верные друзья и яростные враги, они хранят древнейшие сказания гару.",
  "wod.wolf.gaia": "Дети Геи — миротворцы Нации Гару, стремящиеся объединить племена и залечить старые раны. Они ищут гармонии с человечеством и верят, что дипломатия и сострадание в войне со Змием значат не меньше, чем битва. Их Дары служат исцелению, умиротворению и защите. Другие порой называют их наивными, но, когда нужно, они сражаются яростно.",
  "wod.wolf.glass": "Ходящие по Стеклу — городские гару, принявшие города и технологии. Они вращаются в бизнесе, компьютерах и современном обществе, веря, что гару должны приспособиться к современному миру, чтобы выжить. Их Дары служат технике, городской среде и цифровой Умбре. Другие племена часто подозревают их в чрезмерной близости к Ткачихе.",
  "wod.wolf.gnawers": "Грызущие Кости — племя улиц, живущее среди бездомных и бедняков городов. Другие племена смотрят на них свысока, но они находчивые и скромные выживальщики, защищающие тех, о ком общество забыло. Их Дары служат выживанию, добыче пропитания и укрытию. Мало кто знает о происходящем в городе больше, чем они.",
  "wod.wolf.shadow": "Теневые Владыки — честолюбивые и расчётливые гару с корнями в Восточной Европе, верящие, что право вести должны решать сила и хитрость. Они давно оспаривают у Серебряных Клыков главенство в Нации. Их Дары служат устрашению, манипуляции и силе бурь. Их боятся и им не доверяют, но они дисциплинированны и действенны.",
  "wod.wolf.stargazers": "Звездочёты — созерцательные гару с азиатскими корнями, ищущие внутреннего равновесия через медитацию и философию. Они известны своими боевыми искусствами и духовной проницательностью. Их Дары служат ясности, восприятию и самообладанию. Временами они отдалялись от Нации Гару и сближались с оборотнями Востока.",
  "wod.wolf.striders": "Безмолвные Странники — скитальцы египетского происхождения, давным-давно изгнанные с родины и обречённые странствовать без отдыха. Они вестники, разведчики и исследователи, бродящие и по физическому миру, и по Умбре. Их Дары служат скорости, путешествиям и общению с мёртвыми. Одиночки по натуре, они одни из самых осведомлённых среди гару.",
  "wod.wolf.talons": "Красные Когти — племя, целиком состоящее из люпусов, которые считают человечество величайшей угрозой для Геи. Они яростные защитники дикой природы и презирают человеческие города и технологии. Их Дары служат природе, чувствам и разрушению человеческих творений. Многие из них мечтают о дне, когда людей станет столько, сколько способна вынести земля.",
  "wod.wolf.uktena": "Уктена — мистики и хранители тайн, корнями уходящие к коренным народам Америки, хотя они принимают и выходцев из многих других отверженных культур. Они выслеживают и сковывают тёмных духов мира, погружаясь в запретные знания, чтобы никто другой не смог ими злоупотребить. Их Дары служат магии, оккультизму и сокрытому знанию. Другие племена ценят их мудрость, но опасаются рисков, на которые они идут.",
  "wod.wolf.wendigo": "Вендиго — свирепое племя, корнями уходящее к коренным народам Северной Америки. Они глубоко обижены на европейские племена за прошлые несправедливости и защищают свои земли и народы с яростной преданностью. Их Дары служат холоду, ветру и духам зимы. Их тотем — великий дух Вендиго.",
  "wod.banality": "Банальность — леденящая сила неверия, рутины и холодного рассудка, которая медленно убивает Грёзу. Каждый подменыш несёт её в себе, и чем больше Банальности, тем труднее творить кантрипы и помнить о своей фейской природе. Банальные смертные и места способны разрушать волшебство фей и погружать подменышей в забвение. Если её не сдерживать, всё заканчивается Развоплощением: фейская душа угасает, и остаётся лишь смертный.",
  "wod.court.seelie": "Благой двор — летний двор, который по традиции правит обществом фей от Белтайна до Самайна. Его сторонники чтят честь, рыцарство, традиции и долг благородного сословия, а среди его идеалов — «Смерть прежде бесчестья» и «Любовь побеждает всё». Большая часть знати ши и владения Верховного короля следуют благим обычаям. В каждом подменыше есть и благая, и неблагая сторона, и именно благая держит слово и защищает слабых.",
  "wod.court.unseelie": "Неблагой двор — зимний двор, который по традиции властвует от Самайна до Белтайна. Он ценит страсть, свободу и перемены выше долга и обычая; среди его идеалов — «Перемены — это хорошо» и «Страсть прежде долга». Неблагие феи не просто злы, но они не доверяют косной чести и следуют собственным желаниям. Его самое радикальное, скрытое крыло — Теневой двор, замышляющий свергнуть благой порядок.",
  "wod.demon.a.defilers": "Нереиды — изначальное ангельское имя дома Осквернителей, Пятого дома, которых часто называют Ангелами Глубин. В начале времён они правили морями и водами и обращали сердца людей к красоте, истине и вдохновению. Их Знания — Желание, Бури и Метаморфозы. После Падения их дар пробуждать желание обратился к искушению и манипуляции, за что смертные и дали им их имя.",
  "wod.demon.a.devils": "Глашатаи — изначальное ангельское имя дома Дьяволов, Первого дома, вестников Небес. Они были знаменосцами и голосами Бога, несли волю Творца остальному Воинству и вели ангелов за собой. К этому дому принадлежал сам Люцифер, и многие из них стали полководцами восстания. Их Знания — Небожители, Пламя и Сияние.",
  "wod.demon.a.devourers": "Дом Дикой Природы — изначальное ангельское имя дома Пожирателей, Шестого дома. Его ангелы создавали растения и животных и заботились о них, наполняя всё живое силой и инстинктом. Их Знания — Звери, Дикая природа и Плоть. В войне против Небес они научились превращать живые тела в оружие, и голод и ярость тех дней принесли им смертное имя.",
  "wod.demon.a.fiends": "Провидцы — изначальное ангельское имя дома Извергов, Четвёртого дома, ангелов небес и звёзд. Они привели космос в движение и читали великий узор его хода, предвидя, как развернутся события. Их Знания — Свет, Узоры и Порталы. После Падения они стали мастерами пророчества, иллюзий и судьбы, которых смертные научились бояться.",
  "wod.demon.a.malefactors": "Искусники — изначальное ангельское имя дома Преступников, Третьего дома, мастеров творения. Они придали форму камню, почве и металлу мира и создали орудия для его созданий. Их Знания — Земля, Пути и Кузнечное дело. Во время войны они обратили своё мастерство на ковку оружия и страшных артефактов, за что и получили смертное имя.",
  "wod.demon.a.scourges": "Ангелы-Хранители — изначальное ангельское имя дома Кнутов, Второго дома, Ангелов Небесного Свода. Они вдыхали жизнь в новорождённых существ, управляли ветрами и воздухом и оберегали человечество как защитники и целители. Их Знания — Пробуждение, Небесный Свод и Ветер. После Падения те же силы стали способны нести болезни и страдания вместо здоровья.",
  "wod.demon.a.slayers": "Жнецы — изначальное ангельское имя дома Убийц, Седьмого дома, Ангелов Смерти. Их долгом было завершать то, что отжило своё, и возвращать это творению, чтобы оно могло начаться заново. Их Знания — Смерть, Души и Сферы. Когда человечество утратило бессмертие, они стали вестниками истинной смерти, и многие из них создавали царство неупокоенных мёртвых.",
  "wod.demon.defilers": "Осквернители — Пятый дом Падших, чьё ангельское имя — Нереиды. Когда-то они вдохновляли людей красотой морей и движениями сердца, а после Падения стали искусителями, играющими на тоске и желании. Их Знания — Желание, Бури и Метаморфозы: они разжигают чувства, повелевают водой и погодой и меняют облик. Их часто называют музами — порой к добру, порой к худу.",
  "wod.demon.devils": "Дьяволы — Первый дом Падших, Глашатаи, к которым принадлежал Люцифер. Они были вестниками Бога и предводителями Воинства, а в восстании стали его командирами. Гордые, харизматичные и привыкшие вести за собой, Дьяволы владеют Знаниями Небожителей, Пламени и Сияния. Они притягивают других одним своим присутствием и убеждённостью.",
  "wod.demon.devourers": "Пожиратели — Шестой дом Падших, чьё ангельское имя — Дом Дикой Природы. Они были пастырями растений и животных и несут в себе первобытную жизненную силу и голод всего живого. Их Знания — Звери, Дикая природа и Плоть: они повелевают животными, пробуждают природу и перекраивают живые тела. Пожиратели дики, страстны и живут инстинктом.",
  "wod.demon.fiends": "Изверги — Четвёртый дом Падших, чьё ангельское имя — Провидцы. Они были ангелами, которые привели звёзды в движение и читали узор творения. Их Знания — Свет, Узоры и Порталы: иллюзии, проблески судьбы и способность открывать проходы сквозь пространство. Изверги — хладнокровные, расчётливые интриганы, видящие нити, что стоят за событиями.",
  "wod.demon.malefactors": "Преступники — Третий дом Падших, чьё ангельское имя — Искусники. Они были мастерами, которые придали форму земле и создали орудия творения. Их Знания — Земля, Пути и Кузнечное дело: власть над камнем и почвой, над перемещением из места в место и над созданием зачарованных предметов. Преступники — практичные, терпеливые творцы, ценящие долговечные труды.",
  "wod.demon.scourges": "Кнуты — Второй дом Падших, чьё ангельское имя — Ангелы-Хранители. Когда-то они вдыхали жизнь в существ и оберегали людей как целители и защитники. Их Знания — Пробуждение, Небесный Свод и Ветер: они исцеляют или калечат тело, ощущают далёкие события и повелевают воздухом. Многие Кнуты по-прежнему чувствуют стремление защищать смертных, а другие обратили эту силу в мор.",
  "wod.demon.slayers": "Убийцы — Седьмой дом Падших, чьё ангельское имя — Жнецы, Ангелы Смерти. Они завершали то, чьё время прошло, и вели души дальше. Их Знания — Смерть, Души и Сферы: власть над тлением, над душами умерших и над переходами между мирами. Убийцы обычно серьёзны и немногословны и знают о концах больше, чем любой другой дом.",
  "wod.fac.cryptic": "Скрытные — фракция Падших, посвятившая себя познанию. Они хотят узнать правду о замысле Бога, о причинах войны и Падения и, возможно, о смысле самого бытия. Скрытные ведут расследования, собирают знания и разгадывают тайны, веря, что ответы определят, как следует поступать Падшим. Это небольшая и слабо связанная фракция.",
  "wod.fac.faustian": "Фаустианцы — фракция Падших, видящая в человечестве ключ к власти. Они стремятся связать смертных договорами и собирать их Веру, чтобы набраться сил и возобновить войну против Небес. Они прагматичны, честолюбивы и нередко безжалостны в делах с людьми. Их имя отсылает к легенде о Фаусте и его сделке.",
  "wod.fac.luciferan": "Люцифериане — фракция Падших, хранящая верность памяти Люцифера, Утренней звезды, возглавившего восстание. Они верят, что он всё ещё где-то существует, и ждут его возвращения, чтобы снова пойти за ним. А пока они стараются восстановить былую иерархию и дисциплину мятежных армий. Это самая организованная и воинственная из фракций.",
  "wod.fac.ravener": "Жаждущие — фракция Падших, утративших надежду и на победу, и на прощение. Убеждённые, что творение уже не спасти, они стремятся уничтожить как можно больше его в последнем акте неповиновения. Они нигилистичны и жестоки, и другие демоны относятся к ним со страхом и отвращением. Многие из них сблизились с Земными и их замыслами.",
  "wod.fac.reconciler": "Миротворцы — фракция Падших, надеющихся исправить ущерб, нанесённый войной. Они хотят вернуть миру облик Рая, каким он должен был быть, и, возможно, заслужить прощение Бога. Многие трудятся, исцеляя и землю, и людей, а некоторые ищут примирения между Падшими и смертными. Их путь идеалистичен, но труден, ведь Мука Бездны всё ещё тянет их назад.",
  "wod.faith": "Вера — мера силы демона и его связь с божественной искрой творения. После освобождения из Бездны Падшие вынуждены черпать Веру из веры смертных — через поклонение, договоры с рабами и деяния, рождающие преданность. Вера питает воззвания их Знаний и позволяет явить апокалиптический облик. Демон без Веры — немногим больше, чем голос в украденном теле.",
  "wod.fey.boggan": "Богганы — трудолюбивые домашние феи, невысокие и крепкие, с умелыми руками. Они искренне радуются честному труду — стряпне, уборке, ремеслу — и всегда знают последние местные сплетни. Богганы охотно помогают скромным и нуждающимся, но не терпят заносчивости и лени. Их слабость — потребность довести до конца любое начатое дело и помочь тому, кто действительно в беде.",
  "wod.fey.clurichaun": "Клуриконы — родня лепреконов ирландского фольклора: весёлые забияки, любящие выпивку, песни и хорошую драку. Они обаятельны, удачливы и щедры к друзьям, но легко обижаются. Им служат легендарная удача и чутьё на спрятанные сокровища. Их слабость — горячий нрав, из-за которого им трудно стерпеть оскорбление или уклониться от ссоры.",
  "wod.fey.eshu": "Эшу — странствующие феи, чьи корни уходят в мифы Африки, Индии и Ближнего Востока. Они бесконечно странствуют в поисках историй и приключений, и их дар приводит их туда, где происходит что-то важное. Эшу — великолепные рассказчики, для которых гостеприимство священно. Их слабость — безрассудство: они почти не способны отказаться от вызова или рискованного пари.",
  "wod.fey.ghille": "Гилли Ду — феи лесов и всего растущего, родственные духам деревьев и диких мест. Их тела напоминают листья, кору и лозы и меняются вместе со сменой времён года. Они стражи дикой природы, глубоко сочувствующие растениям и всему живому. Города и бетон тяжело давят на них, и большинство избегает городского мира.",
  "wod.fey.nocker": "Нокеры — фейские мастера и изобретатели, гениально собирающие невозможное из Гламура и хлама. Они перфекционисты, которые постоянно, изобретательно и громко ругаются, особенно на собственную работу. Нокеры чинят и создают чудеса, которые не понял бы ни один смертный инженер. Их слабость в том, что во всём, что они строят, есть хотя бы один скрытый изъян.",
  "wod.fey.pooka": "Паки — игривые феи-оборотни, каждая из которых связана с определённым животным: кошкой, лисой, вороном или кроликом. Они умеют принимать облик этого животного и перенимают многие его повадки. Паки — неисправимые шутники, и их главная слабость в том, что они почти никогда не говорят правду прямо: лгут, приукрашивают или отвечают загадками. Друзья узнают, что за их небылицами часто скрывается настоящая теплота.",
  "wod.fey.redcap": "Красные Шапки — самые пугающие из простолюдинов, феи голода и угрозы, названные в честь фольклорных шапок, якобы окрашенных кровью. Они способны прокусить и проглотить почти всё — от дерева до металла. Красные Шапки обожают запугивать и мрачно шутить, и другие феи стараются им не перечить. Их слабость — сама их неприятность: и люди, и животные инстинктивно им не доверяют.",
  "wod.fey.satyr": "Сатиры — феи веселья и необузданной страсти из мифов Древней Греции, с козлиными ногами и рогами. Они любят музыку, вино, танцы и жаркие философские споры, а их песни и пляски способны разжечь страсть в других и на время оттеснить Банальность. Сатиры — быстрые бегуны, не доверяющие сдержанности и скучной рутине. Их слабость — та же страсть: их настроение резко меняется, и им трудно устоять перед искушением.",
  "wod.fey.selkie": "Селки — морские феи из фольклора северных побережий, способные превращаться в тюленей с помощью своих тюленьих шкур. Они глубоко связаны с океаном и его обитателями и часто защищают морскую жизнь. Шкура для селки бесценна: если её потерять или украсть, селки не может сменить облик и сильно слабеет. Вдали от берега многие тоскуют и не находят покоя.",
  "wod.fey.sidhe": "Ши — фейская знать, прекрасные и властные существа, вернувшиеся из Аркадии в 1969 году и притязающие на власть над другими родами фей. Они объединены в благородные дома и правят большинством феодов и королевств. Их неземная грация привлекает внимание, а отказать им ещё труднее. Их слабость — уязвимость перед Банальностью, которая бьёт по ним сильнее, чем по простолюдинам.",
  "wod.fey.sluagh": "Слуаги — бледные, тихие феи теней, тайн и пыльных забытых мест. Они мастерски собирают сведения, слушают гораздо больше, чем говорят, и нередко водят компанию с призраками. Слуаги протискиваются в узкие щели и замечают то, что ускользает от других. Их слабость в том, что они не могут говорить громче шёпота.",
  "wod.fey.troll": "Тролли — огромные, сильные и стойкие феи, прославленные как верные стражи и воины. К клятвам и долгу они относятся предельно серьёзно, и их слово нерушимо. Обычно тролли тихи и терпеливы, но страшны, когда встают на защиту тех, кого оберегают. Их слабость в том, что нарушенная клятва или брошенный долг лишают их огромной силы.",
  "wod.glamour": "Гламур — суть грёз и творчества, жизненная сила фей и самой Грёзы. Подменыши тратят его на кантрипы, на раскрытие истинной фейской природы вещей и на поддержание химерических творений. Они черпают его во вдохновении и искусстве, в общей с смертными Мечтательности и в заветных местах, называемых феодами. Подменыш, лишённый Гламура, скатывается к Банальности и забвению.",
  "wod.house.aesin": "Дом Эйзин — благородный дом, происходящий от скандинавских фей, которые считают себя роднёй асов и ванов из мифов. В основном неблагие, они долгие века провели в ледяном Альфхейме, прежде чем вернуться в мир смертных. Их общество иерархично и воинственно, оно живёт по Девяти добродетелям, среди которых мужество, честь, гостеприимство и опора на себя. Члены дома умеют говорить с лесными зверями, но им трудно видеть в простолюдинах равных.",
  "wod.house.ailil": "Дом Эйлиль — ведущий дом Неблагого двора, прославленный политикой, интригами и долгосрочными замыслами. Его члены предпочитают тонкость и манипуляцию открытому противостоянию, и многие действуют в Теневом дворе. Это искусные дипломаты, которые быстро оценивают положение и пользуются любой возможностью. Их слабость — гордость собственной хитростью, из-за которой им крайне трудно признать ошибку.",
  "wod.house.balor": "Дом Балор — неблагой дом, возводящий свою кровь к фоморам и Балору Дурному Глазу. Устроенный как армия, он считает себя в вечной войне с благим порядком и готовится к Бесконечной зиме, когда будет править. Каждый член дома несёт какое-либо увечье тела или духа, которое считается испытанием, требующим преодоления. В отличие от других ши, они переносят касание холодного железа без помех для себя.",
  "wod.house.beaumayn": "Дом Бомайн — благой дом пророков, основанный рыцарем-провидцем в Мифическую эпоху. Всем его членам во снах и медитациях являются проблески возможного будущего. После давнего скандала дом был заточён в Аркадии и стёрт из памяти, вернулся лишь недавно и до сих пор вызывает подозрения. Его видения привлекают и внимание Теневого двора и таллейнов.",
  "wod.house.daireann": "Дом Дайреанн — древний дом кельтских воинов, целителей и поборников, недавно вышедший из Аркадии. Он не слишком строго примыкает к Неблагому двору, сочетает традиции обоих дворов и следует Трём законам — чести, мести и гостеприимства. Его воины сражаются с почти берсеркерской яростью, обузданной строгим кодексом чести, и редко отступают. Их слабость — любовь к похвальбе, из-за которой у них развязывается язык и выдаются тайны.",
  "wod.house.dougal": "Дом Дугал — благой дом мастеров-кузнецов и ремесленников, незримое сердце ши, снабжающее другие дома оружием, доспехами и изобретениями. Положение в доме определяют мастерство и дела, а не политика. У многих его членов есть телесный недостаток, нередко восполненный приспособлениями собственного изготовления. Тонкая инженерия и хорошо сделанные механизмы способны заворожить их на долгие часы.",
  "wod.house.eiluned": "Дом Эйлунд — дом чародеев, учёных и хранителей тайн, формально благой, но уверенно чувствующий себя в моральных полутонах. Его члены видят в знании силу и чаще служат советниками и стратегами, чем правителями. Их кантрипы необычайно могущественны. Другие дома не доверяют им из-за скрытности, а любопытство постоянно втягивает их в заговоры.",
  "wod.house.fiona": "Дом Фиона — благой дом пылких романтиков и бесстрашных искателей приключений. Его члены всем сердцем отдаются любви, подвигам и битвам и славятся своей отвагой. Они горячи, щедры и верны друзьям. Их слабость — та же страсть: они легко и безрассудно влюбляются, часто в неподходящих спутников, и редко отступают перед опасностью.",
  "wod.house.gwydion": "Дом Гвидион — один из самых могущественных благих домов и дом Верховного короля Конкордии. Его члены считают себя прирождёнными вождями, преданными справедливости, чести и защите своих владений. Это проницательные судьи, которых трудно обмануть. Их слабость — свирепый нрав и подозрительность, способные обернуться гневом, когда задета их гордость.",
  "wod.house.leanhaun": "Дом Лианнан — неблагой дом художников, покровителей и муз, которые взращивают смертных Мечтателей и вызывают к жизни выдающиеся творения. Они харизматичны и изящны и превосходно проявляют себя как артисты, искатели талантов и шпионы. За элегантностью скрывается проклятие: они должны постоянно собирать Гламур у тех, кого вдохновляют, иначе начинают стремительно увядать. Многие тайно поддерживают Теневой двор.",
  "wod.house.liam": "Дом Лиам — изгнанный благой дом, чей основатель, лорд Лиам, был сослан за красноречивую защиту смертных. Его члены — мудрецы, хранители преданий и сказители, которые тихо оберегают людей от Банальности и от фей-хищников. Им легко коснуться смертных Гламуром. Другие феи называют их клятвопреступниками и часто отказываются чтить их клятвы или оказывать им гостеприимство.",
  "wod.house.scathach": "Дом Скатах основан Скатах, легендарной воительницей ирландских мифов. Он стоит в стороне от обоих дворов, отвергает наследственную власть и ценит служение, странствия и воинское искусство. Его члены, которых иногда называют Серыми Странниками, сдержанны, безмолвны в бою и разнообразнее по происхождению, чем другие ши. Единственные среди благородных домов, они прошли Путь подменышей ещё до Разлома, и другая знать нередко относится к ним прохладно.",
  "wod.house.varich": "Дом Варич — неблагой дом из России, происходящий от древних фей, которым там когда-то поклонялись, с корнями в средневековом Новгороде. Он феодален и строго иерархичен и ценит верность, стратегию и тонкую работу с янтарём и золотом. Наблюдая за боем или танцем, члены дома учатся предугадывать их рисунок. Они не могут приносить клятвы любви и обязаны принимать любой брошенный им вызов.",
  "wod.lore.awakening": "Знание Пробуждения — одно из Знаний Кнутов. В эпоху творения оно позволяло ангелам вдыхать искру жизни в новые тела и ограждать подопечных от болезней и ран. В современном мире оно позволяет демону залечивать раны, исцелять болезни и даже возвращать к жизни недавно умерших. При высокой Муке то же знание может насылать болезни и тление.",
  "wod.lore.beasts": "Знание Зверей — одно из Знаний Пожирателей. Оно даёт власть над животными, рыбами и птицами, позволяя демону призывать их, повелевать ими и даже изменять их тела. Когда-то ангелы этого дома пасли с его помощью всех тварей дикой природы. Оно также позволяет демону касаться первобытных инстинктов, общих для людей и зверей.",
  "wod.lore.celestials": "Знание Небожителей — одно из Знаний Дьяволов. На Небесах оно позволяло Глашатаям находить других ангелов, передавать им вести и поддерживать их, а ныне оно опирается на веру смертных. Знающий его демон ощущает присутствие других духовных существ, говорит на расстоянии и призывает силу божественных имён. Это знание связи, власти и святой силы.",
  "wod.lore.death": "Знание Смерти — одно из Знаний Убийц. Изначально оно позволяло ангелам этого дома прерывать жизнь быстро и безболезненно и разлагать мёртвую материю, чтобы творение могло начаться заново. В руках демона оно ускоряет тление, иссушает живое и несёт гибель. Оно отражает долг дома — завершать то, что отжило своё.",
  "wod.lore.earth": "Знание Земли — одно из Знаний Преступников. Оно хранит тайны придания формы камню и почве — от перемещения одного камня до изменения целого ландшафта. Когда-то Искусники создавали и поддерживали с его помощью облик Рая. Демон, владеющий этим знанием, может проходить сквозь камень, воздвигать земляные стены или сотрясать саму землю.",
  "wod.lore.firmament": "Знание Небесного Свода — одно из Знаний Кнутов. Оно возвращает часть всеохватного восприятия, которым когда-то обладали ангелы этого дома, позволяя им чувствовать, когда их подопечные страдают или в опасности. Знающий его демон может воспринимать далёкие места и события и дотягиваться через огромные расстояния. Это знание бдительности и защиты.",
  "wod.lore.flame": "Знание Пламени — одно из Знаний Дьяволов. Оно даёт власть над первозданным очищающим огнём творения — от зажжённой свечи до бушующего пожара. Во время войны оно стало одним из главных орудий Глашатаев. Знающий его демон может вызывать огонь, управлять им, придавать ему форму и защищаться от него.",
  "wod.lore.flesh": "Знание Плоти — одно из Знаний Пожирателей. Оно возникло в войне против Небес, когда ангелы этого дома научились перекраивать живые тела для битвы. С его помощью демон может лепить плоть, отращивать природное оружие, исцелять или искажать живые ткани и укреплять тело. Это одно из самых плотских и пугающих Знаний.",
  "wod.lore.forge": "Знание Кузнечного дела — одно из Знаний Преступников. Это практическая сторона их творческой силы, умение создавать орудия, оружие и предметы дивного качества. Демон с этим знанием может чинить или разрушать вещи и наделять предметы долговечной силой. Многие из самых опасных артефактов войны были созданы именно с его помощью.",
  "wod.lore.light": "Знание Света — одно из Знаний Извергов. Оно охватывает природу света и восприятия, и Провидцы научились обращать его в могущественные иллюзии. Знающий его демон может окутать себя тенью, ослепить врагов и сплести убедительные образы, обманывающие чувства. Оно стало ключевым оружием Извергов в искусстве введения в заблуждение.",
  "wod.lore.longing": "Знание Желания — одно из Знаний Осквернителей и сердцевина мудрости их дома. Оно даёт силу волновать человеческое сердце, пробуждая желание, надежду, печаль или вдохновение. Когда-то ангелы этого дома возвышали с его помощью людей к истине и красоте. После Падения его так же часто используют, чтобы искушать и манипулировать.",
  "wod.lore.paths": "Знание Путей — одно из Знаний Преступников. Оно управляет тем, как физический предмет перемещается из одной точки в другую, — дорогами и путями материального мира. Знающий его демон всегда находит дорогу, может запечатывать или открывать проходы, ускорять или замедлять движение. Это тихое искусство странствия.",
  "wod.lore.patterns": "Знание Узоров — одно из Знаний Извергов. Оно позволяет демону изучать движения Великого замысла и предвидеть беды прежде, чем они случатся. С его помощью Провидцы читают вероятности, видят проблески грядущего и незаметно подталкивают случай и судьбу. Это знание пророчества и предназначения.",
  "wod.lore.portals": "Знание Порталов — одно из Знаний Извергов. Оно хранит тайны мгновенного пересечения реальности и открытия дверей между далёкими местами. Знающий его демон может запирать и отпирать проходы, чувствовать пути сквозь пространство и перемещаться, не преодолевая расстояния. В эпоху творения оно позволяло Провидцам свободно двигаться по вверенному им космосу.",
  "wod.lore.radiance": "Знание Сияния — одно из Знаний Дьяволов. Оно хранит тайны вдохновения и лидерства, и в Эпоху Гнева Глашатаи развили его, чтобы воодушевлять смертных союзников. Знающий его демон может излучать ауру величия, сплачивать последователей, внушать благоговение или ужас и приковывать к себе внимание. Это знание присутствия и предводительства.",
  "wod.lore.realms": "Знание Сфер — одно из Знаний Убийц. Оно касается границ между физическим миром и карманами реальности за его пределами. Жнецы использовали его, чтобы укреплять миры вне космоса и странствовать по ним, и оно легло в основу Царства теней мёртвых. Знающий его демон может ощущать и пересекать границы между мирами.",
  "wod.lore.spirit": "Знание Душ — одно из Знаний Убийц. Оно касается душ умерших, и с его помощью Жнецы могли привязывать духов к местам на Земле, чтобы те не потерялись. Знающий его демон может видеть призраков и говорить с ними, повелевать ими или связывать их. Это знание неупокоенных мёртвых.",
  "wod.lore.storms": "Знание Бурь — одно из Знаний Осквернителей. Оно даёт власть над ветром и волной — от усмирения вод до вызова штормов. С его помощью ангелы этого дома распространили своё влияние с морей на сушу. Знающий его демон может вызывать дождь, повелевать водой и обрушивать ярость непогоды.",
  "wod.lore.transfiguration": "Знание Метаморфоз — одно из Знаний Осквернителей. Оно позволяет демону по желанию менять облик, подстраиваясь под ожидания или желания окружающих. Оно охватывает маски, маскировку и изменение собственной формы. В руках Осквернителей это знание обольщения и обмана не меньше, чем красоты.",
  "wod.lore.wild": "Знание Дикой природы — одно из Знаний Пожирателей. Оно собирает тайны лесов и полей, позволяя демону повелевать растениями и формировать природную среду. Когда-то ангелы этого дома с его помощью заботились обо всём растущем в мире. Знающий его демон может заставить растения расти, увядать или двигаться и обратить саму дикую природу против чужаков.",
  "wod.lore.winds": "Знание Ветра — одно из Знаний Кнутов. Оно управляет потоками воздуха, поддерживающими жизнь, — от лёгкого дыхания до воющей бури. Когда-то ангелы этого дома разносили с его помощью дыхание жизни по миру. Знающий его демон может повелевать ветром, переносить голоса и запахи и даровать или отнимать сам воздух, которым дышат другие.",
  "wod.seem.grump": "Старец — облик подменыша в зрелые годы, последняя пора смертной жизни, прожитой бок о бок с фейской душой. Старцы ближе к Банальности и обладают меньшим запасом Гламура, зато несут богатый опыт, глубокое знание фейских преданий и острый язык. Нередко они хранят традиции и обучают кантрипам; их знают как ворчунов, но ценят за мудрость. Многие подменыши помоложе учатся видеть за их ворчливостью заботу.",
  "wod.seem.wilder": "Юноша — облик молодого взрослого подменыша, чья фейская душа всё ещё ярко пылает. Юноши полны энергии, страсти и бунтарства, жаждут испытать всё и проверить себя на прочность. Они ищут собственный путь и разрываются между благой и неблагой сторонами своей натуры. Именно юноши составляют большинство подменышей-искателей приключений, хотя их порывистость часто приводит к беде.",
  "leg.l.al": "XX легион под командованием примарха Альфария — последнего из найденных примархов. Альфа-Легион воевал с помощью проникновения, дезинформации и многослойного обмана, скрывая агентов и ячейки среди врагов, а своим символом избрал многоголовую гидру. В Ереси он встал на сторону Хоруса, хотя его истинные мотивы до сих пор остаются загадкой.",
  "leg.l.ba": "IX легион под командованием крылатого примарха Сангвиния; его воинов набирали на опалённом радиацией мире Ваал. Кровавые Ангелы — благородные воины и тонкие художники, но в их геносемени скрыто проклятие: Красная Жажда и Чёрная Ярость. Легион остался верен, а Сангвиний пал в бою с Хорусом на борту флагмана Магистра войны во время Осады Терры.",
  "leg.l.da": "I легион, созданный первым; им командовал примарх Лев Эль'Джонсон с лесного мира Калибан. Тёмные Ангелы владели всеми видами войны и хранили множество секретного оружия и тайных орденов. Легион остался верен, однако часть его восстала против Льва, а Калибан был уничтожен; охота на этих Падших с тех пор остаётся их сокровенным позором.",
  "leg.l.dg": "XIV легион под командованием примарха Мортариона, выросшего на ядовитом мире Барбарус. Гвардия Смерти ценила мрачную стойкость, невосприимчивость к ядам и неумолимое наступление. Легион примкнул к Хорусу, а застряв в варпе, был поражён страшной чумой и превратился в раздутых, почти неуязвимых Чумных десантников Нургла.",
  "leg.l.ec": "III легион под командованием примарха Фулгрима, восстановленный почти из небытия на мире Хемос. Дети Императора были одержимы совершенством и удостоились права носить личную аквилу Императора. Гордыня привела их к богу Хаоса Слаанешу, и, став предателями, они отбросили любые пределы в погоне за излишествами и ощущениями.",
  "leg.l.if": "VII легион под командованием примарха Рогала Дорна, прославленный как лучшие строители и защитники укреплений. Имперские Кулаки были стойкими и непреклонными, а домом им служила крепость-корабль «Фаланга». Сохранив верность, они укрепили Императорский дворец и удержали его против предателей во время Осады Терры.",
  "leg.l.ih": "X легион под командованием примарха Ферруса Мануса с сурового мира Медуза. Железные Руки верят, что «плоть слаба», заменяют тела бионикой и ставят холодную логику выше чувств. Оставшись верными Императору, они потеряли своего примарха в Резне в зоне высадки на Истваане V, где Ферруса Мануса убил Фулгрим.",
  "leg.l.iw": "IV легион под командованием примарха Пертурабо с Олимпии — мастера осад и войны на истощение. Железные Воины раз за разом получали изнурительные и неблагодарные осады Великого крестового похода, и с каждой кампанией их горечь росла. Они примкнули к Хорусу; их девиз — «Железо внутри, железо снаружи».",
  "leg.l.nl": "VIII легион под командованием примарха Конрада Кёрза, Ночного Призрака, с лишённого света мира Нострамо. Повелители Ночи воевали террором, ломая целые миры страхом ещё до битвы и во время неё. Они стали предателями, а Кёрз, преследуемый видениями собственной смерти, позволил имперской ассасинке убить себя.",
  "leg.l.rg": "XIX легион под командованием примарха Коракса, освободившего тюремную луну Освобождение. Гвардия Ворона специализируется на скрытности, скорости и точных ударах из тени. Сохранив верность Императору, легион был почти уничтожен в Резне в зоне высадки на Истваане V, но выстоял и восстановился.",
  "leg.l.sal": "XVIII легион под командованием примарха Вулкана с вулканического мира Ноктюрн. Саламандры — искусные кузнецы, сами куют своё оружие, предпочитают огнемёты и мелта-оружие и известны заботой о простых людях. Легион остался верен и тяжело пострадал на Истваане V.",
  "leg.l.soh": "XVI легион, изначально Лунные Волки, переименованный в честь примарха Хоруса Луперкаля, когда тот стал Магистром войны. Сыны Хоруса были первым легионом Императора, пока Хорус не обратился к Хаосу и не возглавил мятеж, ставший Ересью Хоруса. После его гибели легион под командованием Абаддона стал Чёрным легионом.",
  "leg.l.sw": "VI легион под командованием примарха Лемана Русса с ледяного мира Фенрис. Космические Волки — свирепые, неукротимые воины со своими традициями и рунными жрецами, служившие палачами Императора. Сохранив верность, они были посланы против Магнуса Красного, и их удар уничтожил Просперо, родной мир легиона Тысяча Сынов.",
  "leg.l.ts": "XV легион под командованием примарха-псайкера Магнуса Красного с Просперо — самые учёные мыслители и колдуны среди легионов. Тысяча Сынов страдали от мутаций, а опора на психическую силу делала их подозрительными. После сожжения Просперо они примкнули к Хорусу и Тзинчу; позднее Рубрика колдуна Аримана обратила большинство из них в прах внутри запечатанных доспехов.",
  "leg.l.um": "XIII легион под командованием примарха Робаута Жиллимана, правителя Макрагга и державы Ультрамар. Ультрамарины были крупнейшим легионом, прославленным дисциплиной, снабжением и порядком. Они остались верны, а после Ереси Жиллиман написал Кодекс Астартес, разделивший легионы на ордены и до сих пор направляющий большую часть Космодесанта.",
  "leg.l.wb": "XVII легион под командованием примарха Лоргара с Колхиды, почитавшего Императора как бога. После того как Император осудил их при Монархии, Несущие Слово тайно обратились к богам Хаоса. Они первыми из легионов пали перед Хаосом и помогли втянуть Хоруса в мятеж.",
  "leg.l.we": "XII легион, некогда Псы Войны, под командованием примарха Ангрона, бывшего гладиатора. Ангрон заставил своих воинов принять Гвозди Мясника — импланты, наполняющие мозг яростью, и Пожиратели Миров стали самым свирепым из легионов. Они примкнули к Хорусу и целиком отдались Кхорну.",
  "leg.l.ws": "V легион под командованием примарха Джагатая-хана со степного мира Чогорис. Белые Шрамы — мастера молниеносной войны: быстрых ударов, конных и моторизованных атак и неумолимого преследования. Они остались верны, пробились обратно к Терре и помогли защитить Императорский дворец во время Осады.",
  "leg.lost": "Второй и Одиннадцатый легионы отсутствуют во всех имперских записях. Во время Великого крестового похода с ними и их примархами что-то случилось, и их имена и история были намеренно стёрты. Те, кто знает правду, связаны обетом молчания, и ничего достоверного об их судьбе не известно.",
  "ow.grudges": "Даммаз Крон, Великая книга обид, хранится у Верховного короля дворфов в Караз-а-Караке, и в ней записана каждая обида, когда-либо нанесённая народу дворфов. По традиции записи делаются кровью Верховного короля. Обиду вычёркивают, только когда за неё отомщено, а у каждой крепости, клана и семьи есть и своя книга обид.",
  "ow.r.beast": "Зверолюды — рогатые козлоголовые дети Хаоса, таящиеся в глухих лесах Старого Света. Они собираются стадами вокруг священных камней-стадников и ненавидят цивилизацию, нападая на деревни и города, чтобы разрушить созданное людьми. Горы, унгоры, минотавры и чудовища сражаются вместе под началом вожака-зверолорда.",
  "ow.r.bret": "Бретония — королевство рыцарей, которым правит король и которое почитает Владычицу Озера. Знать живёт по кодексу рыцарства, а крестьяне служат ей. Лучшие рыцари отправляются на поиски Грааля; достигшие цели становятся рыцарями Грааля, а мощь королевства держится на атаках тяжёлой конницы.",
  "ow.r.cathay": "Великий Катай — огромная империя на далёком востоке, которой правят Император-Дракон и его дети, древние драконы, способные принимать человеческий облик. Его армии охраняют Великий Бастион — гигантскую стену, сдерживающую силы Хаоса с севера. Катай ценит гармонию и порядок, а его товары попадают в Старый Свет по Пути слоновой кости.",
  "ow.r.cd": "Дворфы Хаоса — потомки дворфов, отрезанных в Тёмных землях и обратившихся к поклонению Хашуту, быкоголовому Отцу Тьмы. Из своего огромного города-зиккурата они правят промышленной державой, построенной на рабском труде, колдовстве и боевых машинах со скованными демонами. Их колдуны обладают великой силой, но постепенно обращаются в камень.",
  "ow.r.de": "Тёмные эльфы — жестокий народ изгнанников из холодной страны Наггарот, которым правит Король-Чародей Малекит. Они поклоняются Кхаину, богу убийства, и со своих чёрных ковчегов совершают набеги по всему миру ради пленников и сокровищ. Их ненависть к родичам, Высшим эльфам, не знает конца.",
  "ow.r.dwarf": "Дворфы — гордый и упрямый народ древних горных крепостей, величайшая из которых — Караз-а-Карак. Они превосходные рудокопы, кузнецы и инженеры, чтут богов-предков, а их рунные кузнецы заключают магию в руны. Дворфы никогда не забывают обид, и их держава, хоть и ослабевшая, продолжает сражаться с орками, гоблинами и скавенами.",
  "ow.r.emp": "Империя — крупнейшее и самое могущественное человеческое государство Старого Света, основанное Зигмаром, которого теперь почитают как бога. Ею правит Император, избираемый курфюрстами её провинций. В её армиях служат государственные войска, рыцари, боевые маги из Коллегий Магии, пороховые орудия и паровые танки.",
  "ow.r.he": "Высшие эльфы — древний гордый народ с острова Ультуан, которым правят Король-Феникс и Вечная Королева. Они непревзойдённые маги и мореходы и поддерживают Великий Вихрь, вытягивающий из мира сырую силу Хаоса. Их дисциплинированные армии копейщиков, лучников и элитных воинов защищают мир от Хаоса.",
  "ow.r.kislev": "Кислев — северное человеческое государство степей и лесов, стоящее между Старым Светом и Пустошами Хаоса. Им правит царь или царица, и правители Кислева нередко владели могучей ледяной магией. Кислевиты выносливы и свободолюбивы, а их армии крылатых уланов, конных лучников и стойкой пехоты сдерживают нашествия с севера.",
  "ow.r.liz": "Люди-ящеры — слуги Древних, живущие в душных джунглях и храмовых городах Люстрии. Ими руководят слаанны — древние маги-жрецы огромной силы, а сражаются они воинами-заурусами, сцинками и огромными ящерами. Их цель — исполнение Великого Плана исчезнувших создателей.",
  "ow.r.ogre": "Огры — огромные вечно голодные громилы из Гор Скорби, поклоняющиеся Великой Пасти, богу бесконечного голода. Их племенами правит сильнейший тиран, а в их брюхе может оказаться что угодно. Многие огры странствуют по миру наёмниками, ценимыми за силу и готовность сражаться за плату или еду.",
  "ow.r.orc": "Орки и гоблины — зеленокожие, выносливая и многочисленная раса, живущая ради драки. Они поклоняются Горку и Морку, и когда появляется сильный вожак, племена собираются в великий Ваааг!, сметающий всё на своём пути. Здоровенные орки и подлые гоблины вместе с троллями и великанами образуют огромные буйные орды.",
  "ow.r.skaven": "Скавены — люди-крысы, живущие в огромной Подземной империи, прорытой под всем миром, со столицей в Скавенблайте. Они поклоняются Рогатой Крысе и подчиняются Совету Тринадцати, а соперничающие кланы плетут интриги друг против друга. С помощью искажающего камня, чумы и странных машин они замышляют захватить поверхность, хотя большинство людей считает их мифом.",
  "ow.r.tk": "Цари гробниц — древние правители Нехекхары, пустынной страны великих пирамид, поднятые из мёртвых страшным ритуалом Нагаша. Связанные со своими телами, они командуют легионами воинов-скелетов и оживлённых изваяний, а обряды совершают жрецы-личи. Они стремятся вернуть утраченное величие своих царств.",
  "ow.r.vamp": "Вампиры — бессмертные аристократы, повелевающие мёртвыми, печально известные прежде всего по проклятой Сильвании. С помощью некромантии они поднимают армии зомби, скелетов и упырей. Их родословные, например фон Карштайны, не раз угрожали Империи.",
  "ow.r.we": "Лесные эльфы — стражи Атель Лорена, зачарованного леса в Старом Свете. Они живут в гармонии с его духами и служат правителям леса, Ориону и Ариэль. Это непревзойдённые лучники, которые стремительно атакуют из-за деревьев, защищая свои владения от любых пришельцев.",
  "ow.r.woc": "Воины Хаоса — смертные чемпионы с ледяного севера, служащие богам Хаоса в надежде на славу и милость. Закованные в тяжёлые доспехи и нередко отмеченные дарами мутаций, они ведут великие нашествия на юг, на цивилизованные земли. Самые любимые богами могут вознестись до демонов, а неудачники — превратиться в безмозглых отродий.",
  "wh.f.aeldari": "Эльдары — древняя раса с сильным психическим даром, чья великая империя рухнула во время Падения, когда их собственные излишества породили бога Хаоса Слаанеша. Выжившие живут на огромных искусственных мирах и следуют строгим Путям, чтобы обуздать свою природу. Они сражаются с помощью изящных технологий и могучих псайкеров и хранят свои души в камнях душ.",
  "wh.f.csm": "Космодесант Хаоса — космодесантники-ренегаты, восставшие против Империума и служащие Губительным Силам. Многие из них — ветераны легионов-предателей, бежавшие в Око Ужаса после Ереси Хоруса и с тех пор ведущие Долгую войну. Они сражаются древним снаряжением, с помощью демонов и мутаций, дарованных их богами.",
  "wh.f.dmech": "Тёмный механикус — техножрецы Марса, вставшие на сторону Хоруса и принявшие Хаос. Они без всяких ограничений добиваются запретных знаний и технологий, заключая демонов в машины и создавая демонические машины. Их творения служат силам предателей по сей день.",
  "wh.f.drukhari": "Тёмные эльдары — жестокие сородичи эльдаров, обитающие в Комморре, тёмном городе, сокрытом в Паутине. Чтобы отсрочить притязания Слаанеш на свои души, они поддерживают себя, причиняя страдания другим. Они совершают стремительные набеги в реальное пространство за пленниками на быстрых антигравитационных машинах и со смертоносными клинками.",
  "wh.f.gk": "Серые Рыцари — тайный орден Космодесанта, полностью состоящий из псайкеров и посвятивший себя борьбе с демонами. Они служат Ордо Маллеус Инквизиции из своей крепости на Титане. Вооружённые немезидовым силовым оружием и защищённые освящёнными доспехами, они — одни из самых неподкупных воинов Империума.",
  "wh.f.harlequins": "Арлекины — загадочные эльдарские воины-артисты, посвятившие себя Цегораху, Смеющемуся Богу. Они странствуют по Паутине труппами, разыгрывая священные мифы и вступая в битвы с акробатическим изяществом. Кроме того, они хранят Чёрную библиотеку — тайное хранилище запретных знаний.",
  "wh.f.ig": "Имперская гвардия, также называемая Астра Милитарум, — огромная армия Империума из бесчисленных полков, набранных на мирах по всей галактике. Её солдаты — обычные люди с лазганами, которых поддерживают танки и артиллерия. Недостаток силы они восполняют численностью, мужеством и бесконечными жертвами.",
  "wh.f.mech": "Механикус — жречество Марса, поклоняющееся Богу-Машине, также называемому Омниссией. Его техножрецы сохраняют и обслуживают технологии Империума, оберегают древние знания и заменяют свою плоть механизмами. В его армиях сражаются скитарии, сервиторы и боевые машины.",
  "wh.f.necrons": "Некроны — древняя раса, чьи живые тела были перенесены в бессмертные металлические оболочки по договору со звёздными богами К'тан. Проспав миллионы лет в своих мирах-гробницах, они пробуждаются, чтобы вернуть себе галактику. Они сражаются гаусс-оружием и пугающими технологиями, а их тела сами себя восстанавливают.",
  "wh.f.orks": "Орки — зеленокожая раса, живущая ради войны и расселившаяся по всей галактике. Они крепки и живучи, а их грубая техника нередко работает лишь потому, что орки в это верят. Когда достаточно орков собирается под началом сильного вожака, они начинают WAAAGH!",
  "wh.f.sm": "Космодесант, также называемый Адептус Астартес, — генетически усовершенствованные воины Империума. Организованные в ордены примерно по тысяче бойцов, они — Ангелы Смерти Императора, которых бросают на самые опасные поля сражений. Облачённые в силовую броню и вооружённые болтерами, они — лучшие солдаты Империума.",
  "wh.f.sob": "Сёстры битвы, также известные как Адепта Сороритас, — военные ордены Экклезиархии, имперской церкви. Они сражаются с непоколебимой верой в Императора, вооружённые болтерами, огнемётами и мелтами. Их вера настолько сильна, что порой проявляется на поле боя в виде чудес.",
  "wh.f.tau": "Тау — молодая технологически развитая раса с Восточной Окраины галактики, объединённая философией Высшего Блага. Их общество разделено на касты и ведомо загадочными Эфирными. Их армии опираются на боескафандры и мощное импульсное оружие, а другие расы они нередко стремятся присоединить мирным путём.",
  "wh.f.tyranids": "Тираниды — пришедший из-за пределов галактики рой, направляемый единым Разумом Улья. Их флоты-ульи путешествуют между звёздами, поглощая всю биомассу на захваченных мирах, чтобы создавать новых существ. Они быстро приспосабливаются к любой обороне и уже пожрали бесчисленное множество миров.",
  "wh.waaagh": "WAAAGH! — это одновременно великий крестовый поход орков и психическая сила, которую порождает большое скопление орков. Когда вожак собирает достаточно последователей, WAAAGH! становится громче и сильнее, притягивая всё новых орков. Чем больше WAAAGH!, тем могущественнее становятся орки.",
  "wr.mut": "Мутации — дары богов Хаоса, знаки милости, искажающие тела их последователей. Это могут быть лишние глаза или конечности, клыки, рога или щупальца. Для чемпиона Хаоса мутации — знаки благосклонности, способные привести к вознесению в демоны, но слишком многие из них превращают его в безмозглое отродье.",
  "wr.of.khorne": "Кхорн — Бог Крови, бог Хаоса войны, ярости и воинской силы, восседающий на троне из черепов. Служить Кхорну — значит сражаться без конца, собирая черепа во имя его и презирая колдовство и трусость. Его последователи верят, что в бою есть честь.",
  "wr.of.nurgle": "Нургл — Бог Чумы, также называемый Дедушкой Нурглом, бог Хаоса болезней и разложения, но также стойкости и возрождения. Его последователи одарены болезнями, делающими их невосприимчивыми к боли и отчаянию. Служить Нурглу — значит принять круговорот жизни и смерти.",
  "wr.of.rat": "Рогатая Крыса — бог скавенов, которого иногда почитают как пятого бога Хаоса. Его последователи коварны, честолюбивы и вероломны и всегда ищут, кого бы предать. Служить Рогатой Крысе — значит строить козни ради того, чтобы скавены правили миром.",
  "wr.of.slaanesh": "Слаанеш — Тёмный Принц, бог Хаоса излишеств, совершенства и ощущений. Его последователи ищут совершенства во всём и всё дальше заходят в погоне за новыми впечатлениями. Служить Слаанешу — значит никогда не знать насыщения.",
  "wr.of.tzeentch": "Тзинч — Изменяющий Пути, бог Хаоса перемен, честолюбия и колдовства. Его последователи — интриганы-колдуны, жаждущие знаний и власти. Служить Тзинчу — значит стать частью его бесконечных замыслов.",
});
